export const GlossaryEntries = [{"id": "access-control", "en": "Access control", "zh_display": "出入口控制系统", "definition_zh": "识别和核验人员或车辆的通行权限，并控制、记录建筑出入口通行的系统，可与其他建筑系统联动。", "scope_note": "", "name_basis": "GB 50314—2015第2.0.7条文说明（3）明确名称及定义；“门禁系统”不作为该条国标原文名。", "evidence_note": "中文工程建设标准定义的概述（研究机构公开文本）", "category": "systems-controls"}, {"id": "acoustic-comfort", "en": "Acoustic comfort", "zh_display": "声环境舒适度〔NTi中文用语〕", "definition_zh": "使用者对空间声音环境适宜程度的感受，与活动需求有关，可涉及背景噪声、隔声、混响及语言隐私，不是单纯越安静越好。", "scope_note": "", "name_basis": "NTi Audio官方中文技术页实际用“声环境舒适度”，并以使用者满意程度解释；它不是IWBI自行发布的中文正式定义，撤去无同源依据的“亦称声舒适”并列。", "evidence_note": "声学设备厂商官方中文技术介绍的概述；非WELL标准原文", "category": "health-occupancy"}, {"id": "affordable-housing", "en": "Affordable housing", "zh_display": "可负担房屋〔香港政府用语〕", "definition_zh": "房屋成本与目标家庭支付能力相适应的住房及相关政策安排；对象、价格、补贴和分配资格依当地制度，不能一律等同经济适用住房。", "scope_note": "", "name_basis": "政府中文用法；制度范围因地而异", "evidence_note": "政府中文用法；制度范围因地而异", "category": "building-types"}, {"id": "air-handling-unit", "en": "Air handling unit", "zh_display": "空气处理机组", "definition_zh": "对空气进行过滤、加热、冷却、加湿或除湿等一种或多种处理，并组织送风的设备；具体功能由机组配置及系统设计确定。", "scope_note": "", "name_basis": "开利自身中文产品目录明确用“空气处理机组”；GB/T 14294—2026正式中英题名是“组合式空调机组／Central-station air handling unit”，仅对应集中组合式类别。", "evidence_note": "厂商中文名称用法与技术概述；标准目录仅证明相关设备名称", "category": "systems-controls"}, {"id": "animal-care-facility", "en": "Animal care facility", "zh_display": "动物照护设施〔政府救护及TAF生物风险管理资料用语〕", "definition_zh": "用于动物饲养照护、诊疗、收容或研究照护等活动的建筑及相关设施，可包括兽医诊所、动物收容所、犬舍和实验动物设施。卫生、防疫、隔离及通风要求应按动物种类、用途及适用规范分别确定。", "scope_note": "这是已有跨场景中文用语，尚未核得把原词全部子类统一规定为一个建筑类别的标准条文。TAF材料属于政府委托研究报告附录，不是政府颁布标准。", "name_basis": "“动物照护设施”并非本次自行组合：林业及自然保育署2025年原文直接以该词描述动物园具备、可用于野生动物救护和医疗的设施；全国认证基金会（TAF）编写的2015年政府委托报告所收录《实验室生物风险管理规范》4.4.4.6，又直接使用“兽医与动物照护设施人员”。前者处于救护医疗及动物园照护场景，后者处于研究/生物风险设施场景，名称已有跨场景上位用法。因而可作为本词条的来源限定中文名称，不再要求单篇材料必须穷举网页全部例子。这里没有声称任一来源已发布Animal care facility这一整类建筑的统一官方定义。", "evidence_note": "政府自行发布的动物救护中文资料与专业认可机构编写的生物风险管理中文规范用语互证；可采用来源限定名称，但未核得覆盖原网页全部子类的统一建筑分类标准条文。释义为依据原词功能范围及所列材料整理的概述。", "category": "building-types"}, {"id": "anomaly-detection", "en": "Anomaly detection", "zh_display": "异常检测", "definition_zh": "识别偏离正常、预期或既定模式的观测值、事件或数据点的方法，可用规则、统计或机器学习；检测到异常不等于已诊断故障。", "scope_note": "", "name_basis": "中文名称和技术解释依据IBM官方中文资料。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "data-software"}, {"id": "api", "en": "API", "zh_display": "应用程序编程接口〔API〕", "definition_zh": "使软件组件按规定的定义、规则和协议请求服务与交换结果的接口机制；REST API只是其中一类，API不自动意味着公开或免费。", "scope_note": "", "name_basis": "新增GY/T402—2024的API中英文对照名称证据；仅以缩略语条目证明命名，未伪称该标准给出本条全部释义。", "evidence_note": "发布部门公开的中文行业标准缩略语证实名称；具体释义另据原有技术提供者说明", "category": "data-software"}, {"id": "artificial-intelligence", "en": "Artificial intelligence", "zh_display": "人工智能〔AI〕", "definition_zh": "使机器或计算机系统表现出推理、学习、感知等通常与人类智能相关功能的能力，以及实现这些能力的技术。建筑应用可用于预测、分类、建议或控制，具体方法不限机器学习。", "scope_note": "", "name_basis": "改写“功能单元”以适合文档读者，仍沿用已核政府指南的能力概念；不以单一机器学习方法定义全部人工智能。", "evidence_note": "政府中文监管指南术语概述，另有国标名称证据", "category": "data-software"}, {"id": "ashrae-223p", "en": "ASHRAE 223P", "zh_display": "ASHRAE 223P", "definition_zh": "用于建筑系统信息语义建模的拟议ASHRAE标准项目，通过形式化概念与关系表达设备、空间、测控点及其上下文，支持软件自动理解和使用建筑数据。", "scope_note": "", "name_basis": "保留ASHRAE223P标准项目编号；不自行创造正式中文题名。ASHRAE官方目录本轮仍标Proposed Standard。", "evidence_note": "ASHRAE官方目录直接支持拟议标准项目身份、题名、目的和范围；未核得制定方正式中文名称/定义，中文释义为英文一手资料的概述。", "category": "protocols-standards"}, {"id": "asset-register", "en": "Asset register", "zh_display": "资产登记册〔香港机电工程署建筑运维用语〕", "definition_zh": "记录资产身份、位置及相关信息，支持清查、维护和管理的结构化记录；具体设备参数、保修与维修史字段由管理目的决定。", "scope_note": "", "name_basis": "补得机电工程署建筑电气设备运维资料的同领域中文用法，不必再只借社署固定资产场景而保留英文主名。", "evidence_note": "政府发布的建筑设备操作维修中英文材料用语及管理要求；非独立全国术语标准", "category": "data-software"}, {"id": "automated-shading", "en": "Automated shading", "zh_display": "自动遮阳〔路创、尚飞中文用语〕", "definition_zh": "根据太阳位置、光照、室内环境或时程等条件，自动调节百叶、遮阳帘等装置的位置或角度，以控制眩光、天然采光和太阳得热；可与照明和暖通控制协同。", "scope_note": "", "name_basis": "路创Quantum中文资料印刷页6使用“自动遮阳”，页12标题为“自动遮阳控制”，解释随太阳位置调节遮阳帘以控制眩光及日照得热。尚飞中英多语手册中文第7节亦直接使用“自动遮阳功能”。已具备可采用的中文行业用语，不必继续以未取得统一标准名为由全部保留英文。", "evidence_note": "头部遮阳及照明控制企业发布的中文资料直接用语；另有地方标准相关系统用语。释义为据这些一手资料整理的概述，并非统一标准逐字定义。", "category": "systems-controls"}, {"id": "bacnet", "en": "BACnet", "zh_display": "BACnet", "definition_zh": "用于建筑自动化和控制设备交换信息的标准通信协议，以规定的对象、属性和服务表达数据；实际互通取决于设备实现的功能。", "scope_note": "", "name_basis": "保留制定方原名／标准编号；中文说明是应用或范围描述，不自行拼接成正式中文专名。中文解释依据ABB官方中文技术文档；BACnet为协议原名，括号内容为描述性名称，不宣称统一国标中文全称。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "protocols-standards"}, {"id": "battery-storage", "en": "Battery storage", "zh_display": "电池储能", "definition_zh": "利用可充电电池将电能转为化学能储存，再按需要释放电能；可用于移峰和电网服务，备用供电须另具备相应系统条件。", "scope_note": "", "name_basis": "“电池储能”为国家能源局使用的名称；介绍依据实验室技术说明，非援引一条统一中文定义。", "evidence_note": "官方中文用法或相关概念＋一手技术资料综合概述，非统一中文定义条文", "category": "energy-sustainability"}, {"id": "biobased-materials", "en": "Biobased materials", "zh_display": "生物基材料", "definition_zh": "本建筑词条主要指全部或部分来源于生物质的材料；生物基来源不自动证明材料可生物降解、低碳或环境表现更好。中国GB/T39514—2020的政府解读另采用包含生物制造途径的较广表述，应说明所采用的定义及含量标识口径。", "scope_note": "", "name_basis": "中文名称与定义依据国家标准解读；最后一句用于明确概念边界。 第六轮名称维持，定义范围按本轮来源补充。", "evidence_note": "中国标准主管部门解读与ISO建筑术语的定义口径分别说明；主释义按建筑材料来源概述，未将政府背景解读伪称已读取的国标逐字条文", "category": "energy-sustainability"}, {"id": "biodiversity", "en": "Biodiversity", "zh_display": "生物多样性", "definition_zh": "各种来源生物体的多样程度，包括物种内部、物种之间及生态系统的多样性，不仅指绿化面积或物种数量。", "scope_note": "", "name_basis": "前句据公约正式中文用语概述；建筑场地表述为适用语境说明。", "evidence_note": "公约中文作准文本定义概述", "category": "energy-sustainability"}, {"id": "biophilic-design", "en": "Biophilic design", "zh_display": "亲自然设计〔浙江省导则用语〕", "definition_zh": "把自然环境、天然材料、自然图案、植物、水景等融入建筑及场地，以建立人与自然联系的设计方法，范围超出摆放植物。", "scope_note": "", "name_basis": "浙江住建厅公开《浙江省小城镇绿色建筑设计导则》9.4.3直接以“亲自然设计”为题并解释设计要求；HKGBC中文指南B.4另用“亲生物性设计”，不宣称唯一统一中文名称。", "evidence_note": "政府中文设计导则实质内容的概述；不是国家标准独立定义", "category": "health-occupancy"}, {"id": "bluetooth-low-energy", "en": "Bluetooth Low Energy", "zh_display": "低功耗蓝牙〔Bluetooth LE／BLE〕", "definition_zh": "蓝牙技术联盟定义的低功耗无线通信方案，工作于2.4 GHz频段，支持连接和广播等方式；蓝牙Mesh和信标属于相关应用或组网方式。", "scope_note": "", "name_basis": "官方中文页面采用“低功耗蓝牙”；“蓝牙低功耗”亦出现在联盟中文资料中。", "evidence_note": "制定／标准组织自身中文资料概述", "category": "protocols-standards"}, {"id": "boiler", "en": "Boiler", "zh_display": "锅炉", "definition_zh": "利用燃料、电力或其他热源，将所容纳工质加热至规定参数并输出热能的设备。建筑供暖锅炉的范围不等于特种设备法规的全部监管范围。", "scope_note": "", "name_basis": "《特种设备安全监察条例》第99条使用“锅炉”并规定设备与监管边界。", "evidence_note": "中文行政法规设备释义的概述", "category": "systems-controls"}, {"id": "breeam", "en": "BREEAM", "zh_display": "BREEAM", "definition_zh": "BRE开发的建筑环境可持续性评估与认证体系，按项目类型和生命周期阶段设置不同方案，通过能源、健康、水、材料等类别评价项目。", "scope_note": "", "name_basis": "官方中文手册保留BREEAM品牌名，未据该文件确认唯一中文展开名；中文译本仅供指导，项目认证以英文方案文件为准。", "evidence_note": "制定组织中文手册概述", "category": "certifications-ratings"}, {"id": "brick-schema", "en": "Brick Schema", "zh_display": "Brick Schema", "definition_zh": "开放的建筑数据语义本体，用于描述设备、数据点及相互关系，帮助不同软件解释和使用建筑运行数据。", "scope_note": "", "name_basis": "机电工程署官方中文资料仍写Brick Schema；未设中文专名，应沿用英文。", "evidence_note": "官方中文内容有据概述（范围及版本见文）", "category": "protocols-standards"}, {"id": "building-automation", "en": "Building automation", "zh_display": "建筑自动化；楼宇自动化", "definition_zh": "依据时程、设定值和传感信息，自动监测、调节及优化建筑设备运行的技术与活动，可由房间、设备和管理等层级协同实现。", "scope_note": "", "name_basis": "标准题名＋厂商中文说明", "evidence_note": "标准题名＋厂商中文说明", "category": "fundamentals"}, {"id": "building-automation-and-control-system-classes", "en": "Building automation and control system classes", "zh_display": "BACS能效等级〔西门子中文资料用语〕", "definition_zh": "按建筑自动化、控制和技术管理功能及其对能源消耗的影响进行分级的框架，通常包括A、B、C、D等级；不等同整栋建筑的综合能效评级。具体功能要求及等级判定应核对所采用的EN ISO 52120-1版本。", "scope_note": "", "name_basis": "西门子中文原文明确使用“BACS能效等级”并列出A高效、B先进、C标准、D低效，不应继续仅因未查到完整英文标题的逐字中文对应而全部保留英文。该资料引用旧EN15232，不能据此宣称中文ISO52120-1版本已经发布。", "evidence_note": "已核实制造商官方中文用语；等级技术范围依据ISO英文标准资料；不是已核实的ISO官方中文译名", "category": "systems-controls"}, {"id": "building-envelope", "en": "Building envelope", "zh_display": "围护结构〔本词主要指外围护部分〕", "definition_zh": "分隔建筑室内外的外墙、屋面、门窗、地面等构件。中文GB 50176的“围护结构”还包括建筑内部使用空间之间的分隔构件。", "scope_note": "", "name_basis": "中文标准条文概述", "evidence_note": "中文标准条文概述", "category": "fundamentals"}, {"id": "building-information-modelling", "en": "Building information modelling", "zh_display": "建筑信息模型〔BIM〕", "definition_zh": "对建设工程和设施的物理、功能特性进行数字化表达，并组织和使用相关信息以支持生命周期协作；须区分建模活动与模型成果。", "scope_note": "", "name_basis": "规范主名称展示，移去“含建模活动语境”这一编辑性标注；释义继续明确英文modelling活动与model成果的关系。 已有GB/T51212—2016发布公告及政府发布地方标准对其术语条文的引述，不应将全部依据笼统标为厂商资料。", "evidence_note": "国家标准发布公告及政府发布地方标准对国家标准条文的引述；此处释义为概述", "category": "data-software"}, {"id": "building-management-system", "en": "Building management system", "zh_display": "楼宇管理系统〔企业中文用语〕；建筑设备管理系统〔GB 50314语境〕", "definition_zh": "用于监测、控制和管理建筑暖通空调及其他设备运行的系统，通常连接现场传感器与执行器、控制器及监控界面；集成范围按项目确定。GB 50314中的建筑设备管理系统另强调对建筑设备监控与公共安全等系统的综合管理。", "scope_note": "", "name_basis": "施耐德中国官方楼宇管理系统用语＋GB 50314—2015第2.0.6条建筑设备管理系统/building management system。", "evidence_note": "制造商官方中文支持楼宇管理系统及监测控制范围；GB 50314公开条文支持建筑设备管理系统这一特定中英术语，释义并列说明语境差异。", "category": "systems-controls"}, {"id": "building-performance-standard", "en": "Building performance standard", "zh_display": "建筑性能标准〔NREL中文用语〕", "definition_zh": "要求适用建筑在规定期限达到特定能源或排放性能水平的政策工具；对象、指标、合规措施、豁免及处罚依具体辖区制度确定。", "scope_note": "", "name_basis": "美国NREL发布的正式中文《SEED平台建筑性能标准实施指南》采用“建筑性能标准（BPS）”，替换前版参考译称“建筑绩效标准”。", "evidence_note": "国家实验室中文政策说明；英文政府定义补充", "category": "energy-sustainability"}, {"id": "campus", "en": "Campus", "zh_display": "园区〔华为及建筑设计企业用语〕", "definition_zh": "在同一场址内，由多栋建筑及其相关空间组成、共同拥有或统一管理的建筑群，可用于大学、企业、医院等。具体统计或认证制度对主要用途、产权和申报边界可能另有要求。", "scope_note": "", "name_basis": "华为《智慧园区2030》印刷页04明确说明现代Campus从校园扩展为通用园区，并非仅园区网络产品名称；大元建筑工场项目中文也直接写“整体园区(campus)”。足以采用有出处的企业中文名称，不再全面保留英文；这不是全国统一标准定义，也不把全部园区都视为EPA统计中的单一物业。", "evidence_note": "华为正式中文报告直接讨论Campus由校园走向通用园区；建筑设计企业项目原文直接使用“园区(campus)”。广义物业定义仍据EPA英文资料概述。", "category": "building-types"}, {"id": "carbon-budget", "en": "Carbon budget", "zh_display": "碳预算", "definition_zh": "在温控目标语境下，指在给定概率及其他气候强迫因素假设下，将升温限制于某水平所允许的全球累计人为净二氧化碳排放上限；从指定近期日期起算的称剩余碳预算。建筑项目预算须另说明分配方法、核算期间和排放边界。", "scope_note": "", "name_basis": "SBTi正式中文术语表v1.3第33页，名称“碳预算/全球碳预算”。 第六轮名称维持，定义范围按本轮来源补充。", "evidence_note": "中文名称据既有组织中文术语；精确温控含义据IPCC AR6已发布英文术语表概述，建筑份额不当作全球定义自动推出", "category": "energy-sustainability"}, {"id": "carbon-capture-and-storage", "en": "Carbon capture and storage", "zh_display": "二氧化碳捕获和封存〔SBTi用语〕", "definition_zh": "捕集二氧化碳，并经处理、运输将其长期封存，使其与大气隔离的过程。IPCC常将工业和能源点源的捕集封存称为CCS；直接从环境空气捕集后再封存通常称DACCS。仅有直接空气捕集（DAC）或碳利用，均不自动表示已实现长期封存。", "scope_note": "", "name_basis": "IMO中文正文用“碳捕集与封存”；SBTi中文词典用“二氧化碳捕获和封存”。 第六轮名称维持，定义范围按本轮来源补充。", "evidence_note": "中文名称据SBTi等中文资料；CCS、DAC及DACCS关系据IPCC已发布英文术语表及工作组FAQ概述，未将点源避免排放与大气移除混同", "category": "energy-sustainability"}, {"id": "childcare-centre", "en": "Childcare centre", "zh_display": "幼儿中心〔香港政府用语〕", "definition_zh": "为幼儿提供日间照护并可结合适龄教育的处所；具体年龄与服务范围依地区制度，大陆“托育机构”不能覆盖全部学前教育例子。", "scope_note": "", "name_basis": "既有香港政府双语证据已直接支持幼儿中心，中文名称栏没有必要再先列一次英文；年龄与服务范围继续标注法域差异。", "evidence_note": "既有政府直接双语用法，清除中文栏冗余英文", "category": "building-types"}, {"id": "chiller", "en": "Chiller", "zh_display": "冷水机组", "definition_zh": "通过制冷循环从水或其他载冷介质中移走热量，提供冷却介质的设备；可服务空调或工艺冷却，不能仅按使用场所定义。", "scope_note": "", "name_basis": "GB 19577—2024正式题名使用“冷水机组”；名称已核，释义为相关设备概述，非宣称从该标准取得单一完整术语条文。", "evidence_note": "中文标准设备名称及范围的概述", "category": "systems-controls"}, {"id": "circadian-lighting", "en": "Circadian lighting", "zh_display": "昼夜节律照明〔SMUD中文用语〕", "definition_zh": "以支持人体昼夜节律为目标安排照明的时间、光强、光谱及持续时长的照明思路，评价须关注实际到达人眼的光暴露；仅能调色温不等于达到该目标。", "scope_note": "", "name_basis": "补足影响节律效应的光强、光谱与持续时长，继续依据CIE立场文件，不把调色温或以人为本照明当作严格同义词。", "evidence_note": "公共机构中文名称用法；CIE英文立场文件中文概述", "category": "health-occupancy"}, {"id": "circular-construction", "en": "Circular construction", "zh_display": "循环建造〔中瑞合作研究用语〕", "definition_zh": "通过保留建筑、延长寿命、构件再利用、可拆卸设计和材料循环，使材料持续发挥价值并减少废弃物的建造与管理方式。", "scope_note": "", "name_basis": "中瑞零碳建筑合作项目官方发布的中英材料使用“循环建造／Circular Construction”；是项目技术用语，未确认统一国标定义。", "evidence_note": "政府合作项目中文研究定义", "category": "energy-sustainability"}, {"id": "co2-monitoring", "en": "CO2 monitoring", "zh_display": "室内二氧化碳浓度监测", "definition_zh": "测量室内二氧化碳浓度，并结合人员活动和通风条件解读，用于辅助通风评估或控制；不能单独代表整体室内空气质量。", "scope_note": "", "name_basis": "天津住建部门公开技术标准说明使用“室内二氧化碳浓度监测装置”；此处以相同监测功能核对中文用法，非独立国标术语条文。", "evidence_note": "政府中文监测要求与ASHRAE英文技术说明的概述", "category": "health-occupancy"}, {"id": "cobie", "en": "COBie", "zh_display": "COBie；建研所用语：建筑设施维护管理信息交付标准", "definition_zh": "组织和交换设计施工阶段形成、设施运行维护所需的结构化信息的方法，涉及空间、设备、型号、保修和维护要求等，常以工作表交付。", "scope_note": "", "name_basis": "内政部建研所2016年《建筑简讯》直接使用“建築設施維護管理資訊交付標準(COBie)”；这是政府中文用法，并非声称国际COBie制定方授权中文全称。COBie-TW为另行本土化研究。", "evidence_note": "官方中文内容有据概述（范围及版本见文）", "category": "protocols-standards"}, {"id": "combined-heat-and-power", "en": "Combined heat and power", "zh_display": "热电联产〔CHP〕", "definition_zh": "在同一能源转换过程中同时生产电力和可利用热能的技术或系统；既可用于现场机组，也可服务集中电厂及区域热网。", "scope_note": "", "name_basis": "机电工程署亦列“汽电共生”；建筑语境采用大陆普遍使用的“热电联产”。", "evidence_note": "政府中文技术定义概述", "category": "energy-sustainability"}, {"id": "commissioning", "en": "Commissioning", "zh_display": "综合效能调适〔公共机构标准用语〕", "definition_zh": "通过策划、检查、测试、验证和记录，确认建筑及系统满足业主项目需求和设计意图的系统化过程；可贯穿前期策划、设计、施工、交付和运行阶段，也可针对既有建筑实施。", "scope_note": "", "name_basis": "中文标准条文＋政府英文说明概述", "evidence_note": "中文标准支持综合效能调适用语；较广commissioning过程范围据ASHRAE英文一手资料概述，非声称同一中文标准逐字定义。", "category": "fundamentals"}, {"id": "computer-aided-facility-management", "en": "Computer-aided facility management", "zh_display": "计算机辅助设施管理〔CAFM〕", "definition_zh": "利用软件协调和优化设施运行、维护、空间及资产管理的方式与解决方案；与CMMS、IWMS功能交叠但并不完全同义。", "scope_note": "", "name_basis": "名称依据IBM官方中文页；不是中国统一的软件分类或强制配置要求。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "data-software"}, {"id": "converged-network", "en": "Converged network", "zh_display": "融合网络〔厂商中文用语〕", "definition_zh": "将楼宇IT、安防及建筑系统接入共同IP基础设施的架构，业务间仍可采用逻辑分段、访问控制和不同服务等级。", "scope_note": "", "name_basis": "官方中文资料使用“融合网络”，此处按智能楼宇共用网络基础设施的语境解释，不是某个单一国际标准的专有名称。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "connectivity"}, {"id": "corporate-sustainability-reporting-directive", "en": "Corporate Sustainability Reporting Directive", "zh_display": "企业可持续发展报告指令〔CSRD；中文转述名〕", "definition_zh": "欧盟要求适用企业披露可持续发展风险、机会及活动影响的指令，配合欧洲可持续发展报告准则实施；适用范围和过渡安排须按现行修法执行。", "scope_note": "", "name_basis": "商务部使用本中文名称，并非欧盟法定中文文本。2026年规则将欧盟企业主要门槛收窄至员工超过1000人且净营业额超过4.5亿欧元；具体对象和过渡依法律。", "evidence_note": "政府中文名称用法；欧盟英文正式指令的中文概述", "category": "certifications-ratings"}, {"id": "cradle-to-cradle", "en": "Cradle to cradle", "zh_display": "摇篮到摇篮", "definition_zh": "从设计阶段考虑材料与制程安全，使材料安全进入生物循环或持续进入工业技术循环的设计理念；区别于具体产品认证计划。", "scope_note": "", "name_basis": "台湾环境部门发布的中文材料明确使用“搖籃到搖籃（C2C）”；不再沿用无来源限定的扩写名称。", "evidence_note": "政府中文实质说明", "category": "energy-sustainability"}, {"id": "crrem", "en": "CRREM", "zh_display": "CRREM；碳风险房地产监测〔其历史中文指引用语〕", "definition_zh": "依据科学减碳路径比较房地产能源和排放强度，支持目标设定及转型风险管理的路径、指南与工具体系；偏离路径不等于已确定贬值。", "scope_note": "", "name_basis": "CRREM官网中文指引使用“碳風險房地產監測”，并有“碳風險房地產監測器”变体；专名仍保留CRREM，不替它另定唯一中文全称。", "evidence_note": "制定组织中文历史指引及当前英文更新", "category": "energy-sustainability"}, {"id": "dali", "en": "DALI", "zh_display": "数字可寻址照明接口〔DALI〕", "definition_zh": "专用于数字照明控制的通信协议，支持设备寻址、单灯、分组和广播控制及相应反馈；DALI-2是基于该协议的认证计划。", "scope_note": "", "name_basis": "中文名称得到乐鑫官方中文技术文档支持；联盟公开中文手册下载需填写资料，未将未取得的手册内容当作已核实证据。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "protocols-standards"}, {"id": "data-centre", "en": "Data centre", "zh_display": "数据中心", "definition_zh": "为集中电子信息设备提供运行环境的建筑场所，可为一栋、数栋或一栋的一部分，包含主机房及相关辅助、支持和管理空间。", "scope_note": "", "name_basis": "中文工程标准条文概述", "evidence_note": "中文工程标准条文概述", "category": "building-types"}, {"id": "daylight-harvesting", "en": "Daylight harvesting", "zh_display": "日光采集〔飞利浦产品用语〕", "definition_zh": "根据空间获得的天然光，自动调暗或关闭部分电照明，以在满足照明需求的同时减少照明用电。", "scope_note": "", "name_basis": "飞利浦MasterConnect官方中文产品页明确用“日光采集”；未核得作为通用标准术语的“天然光补偿控制”，撤去该自组合名称。", "evidence_note": "厂商中文名称用法；政府英文技术资料的中文概述", "category": "systems-controls"}, {"id": "degree-days", "en": "Degree days", "zh_display": "度日数", "definition_zh": "把温度相对规定基准、用于供暖或供冷的正温差按时间累计的气候指标，须明确HDD或CDD、基准温度及统计算法。", "scope_note": "", "name_basis": "中文标准存在“采暖度日数”“供暖度日数”等用语；不能将℃·d误作普通天数。", "evidence_note": "官方中文用法或相关概念＋一手技术资料综合概述，非统一中文定义条文", "category": "energy-sustainability"}, {"id": "demand-response", "en": "Demand response", "zh_display": "需求响应〔DR〕", "definition_zh": "以价格、经济激励等引导用户按电力系统需要调整用电行为，以支持削峰填谷、系统灵活性和可再生能源消纳。", "scope_note": "", "name_basis": "名称及基本含义依官方办法；建筑参与方式为语境说明。", "evidence_note": "政府办法中文法定定义概述", "category": "energy-sustainability"}, {"id": "demand-controlled-ventilation", "en": "Demand-controlled ventilation", "zh_display": "按需控制通风〔DCV〕", "definition_zh": "依据实际人员或相关需求信号调节通风量的控制方式；二氧化碳可作输入之一，但不能单独代表全部室内空气质量。", "scope_note": "", "name_basis": "旭化成微电子官方中文技术页中英直接列“按需控制通风（DCV：Demand Controlled Ventilation）”；为厂商用法，非已核统一国标定义。", "evidence_note": "厂商官方中文技术说明的概述", "category": "systems-controls"}, {"id": "desk-booking", "en": "Desk booking", "zh_display": "办公桌预订", "definition_zh": "通过软件提前或到场后预留共享办公桌或工位的功能；预订表示使用意图，实际到场和占用须结合签到或其他信息确认。", "scope_note": "", "name_basis": "Microsoft正式中文页面直接使用“办公桌预订”；本轮仅采用该有据用语，不自行添加更顺口但未经同页逐字确认的专名。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "data-software"}, {"id": "destination-dispatch", "en": "Destination dispatch", "zh_display": "目的选层系统〔通力用语〕", "definition_zh": "依据乘客的目的楼层信息对乘客分组并分配电梯，以减少不必要停站、优化运载和客流；通常在候梯时输入目的楼层，混合式配置也可保留部分轿厢内选层。", "scope_note": "", "name_basis": "通力中国官方“目的选层解决方案”使用“目的选层系统”；前版“目的选层控制”不作为该来源原文名称。", "evidence_note": "厂商官方中文系统说明的概述", "category": "systems-controls"}, {"id": "dgnb", "en": "DGNB", "zh_display": "DGNB认证体系", "definition_zh": "DGNB建立的建筑可持续性评价与认证体系，以生命周期为基础评价环境、经济、社会文化及功能、技术、过程和场址等质量。", "scope_note": "", "name_basis": "DGNB自己的官网发布《DGNB认证体系—新建建筑标准集：2020国际版中文》，可用文件自称“DGNB认证体系”。", "evidence_note": "取得制定组织正式中文标准集及评估结构说明；引用范围为2020国际版，不称全部现行方案皆同一版本。", "category": "certifications-ratings"}, {"id": "digital-building-logbook", "en": "Digital building logbook", "zh_display": "数字建筑日志〔江苏省质量和标准化研究院平台用语〕", "definition_zh": "汇集或关联建筑相关数据的共用资料库，可包括能源绩效证书、改造护照、智慧就绪信息及全生命周期全球变暖潜势等数据，供建筑相关方共享信息和作出决策；不等同单个BIM模型或施工日志。", "scope_note": "", "name_basis": "另直接核到独立中文用法：江苏省技术性贸易措施信息平台2026-09-15报道2027年度工作计划草案时，后半另回顾2026年AUWP的实施状态，明确写“第32项数字建筑日志标准请求在准备”；该站版权为江苏省质量和标准化研究院。此报道不是上海平台2026-04-08报道的同篇原出处，两者只作各自独立的中文用法证据。欧盟官方2026年度工作计划行动32直接列Digital building logbooks，可核所指。可采用机构平台来源限定名称，不称欧盟法定中文或已发布DBL标准。", "evidence_note": "江苏省质量和标准化研究院技术性贸易措施平台自行发布中文资讯中的译称；上海商务政府平台转载亦可见同词；与欧盟行动32核对所指；非欧盟正式中文名或独立标准定义", "category": "data-software"}, {"id": "digital-twin", "en": "Digital twin", "zh_display": "数字孪生", "definition_zh": "通过数据连接与现实对象或过程保持相应状态同步的数字化表示，结合历史与运行数据支持监测、分析、模拟、预测或决策；同步频率和保真程度应由用途确定。", "scope_note": "", "name_basis": "浙江政府发布DB33/T2350-2022第3.2.3.7直接采用“数字孪生”；使用2022版定义并说明地方标准背景，不冒充当前所有国际标准唯一定义。 第六轮名称维持，定义范围按本轮来源补充。", "evidence_note": "中文名称有地方标准依据；同步特性据Digital Twin Consortium正式定义及NIST英文说明概述，不冒称统一官方中文定义", "category": "data-software"}, {"id": "direct-digital-control", "en": "Direct digital control", "zh_display": "直接数字控制〔DDC〕", "definition_zh": "数字控制器接收现场信号、执行控制逻辑，并直接向受控设备输出控制指令的方式；输入输出不必全部都是数字量。", "scope_note": "", "name_basis": "西门子《APOGEE顶峰系统设计手册》中文用“直接数字控制”；属于厂商技术文档。", "evidence_note": "厂商中文手册内容概述；历史产品资料不作现行标准", "category": "systems-controls"}, {"id": "display-energy-certificate", "en": "Display Energy Certificate", "zh_display": "DEC；显示能源效能证书〔GRESB用语〕", "definition_zh": "依据建筑实际计量能耗并与同类建筑基准比较形成运行能源评级，按适用制度向公众展示的证书，并配有相关改进建议报告。", "scope_note": "", "name_basis": "新增GRESB官方中文用法“显示能源效能证书”，与政府研究用语不同；保留英文，不把任一译名称为英国制定方正式译名。", "evidence_note": "有政府中文制度介绍，尚未检得英国政府正式中文版定义；中文报告不取代各英国地区制度原文。", "category": "certifications-ratings"}, {"id": "distributed-antenna-system", "en": "Distributed antenna system", "zh_display": "分布式天线系统〔DAS〕", "definition_zh": "通过分布于建筑内的多个天线及配套传输、射频设备，扩展蜂窝移动信号覆盖的系统，区别于Wi-Fi接入点网络。", "scope_note": "", "name_basis": "中文名称依据康普官方中文资料；不将所有室内覆盖方案统称DAS。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "connectivity"}, {"id": "district-heating", "en": "District heating", "zh_display": "集中供热", "definition_zh": "由集中热源通过管网为区域内多栋建筑供应热量的系统；热源可多样，集中供冷属于另一概念。", "scope_note": "", "name_basis": "国家标准《集中供热系统能耗评价方法》英文明确使用district heating；为名称对照证据，非声称已读取其定义条文。", "evidence_note": "官方中文用法或相关概念＋一手技术资料综合概述，非统一中文定义条文", "category": "energy-sustainability"}, {"id": "do-no-significant-harm", "en": "Do No Significant Harm", "zh_display": "无重大伤害原则（DNSH）", "definition_zh": "欧盟分类法中的原则：活动在对环境目标作出实质贡献时，不得对其他环境目标造成重大损害，判断依法律和技术筛选标准进行。", "scope_note": "", "name_basis": "欧委会发布的IPSF双语FAQ确有无重大伤害；可采用其正式出版中文用语，但非欧盟法律法定中文文本。", "evidence_note": "欧委会网站正式发布的IPSF中英FAQ中文用语；非法定中文法律文本；法律定义仍核欧盟正式语言原文", "category": "certifications-ratings"}, {"id": "double-skin-facade", "en": "Double-skin facade", "zh_display": "双层幕墙", "definition_zh": "由内外两层立面及其间空气腔构成，通过腔体通风和热工设计管理传热与太阳得热的围护系统；不等同中空玻璃。", "scope_note": "", "name_basis": "官方发布的规范材料提供中文用语和构造说明；不将该文件中的特定构造要求当成所有双层立面的统一定义。", "evidence_note": "官方中文用法或相关概念＋一手技术资料综合概述，非统一中文定义条文", "category": "energy-sustainability"}, {"id": "economiser", "en": "Economiser", "zh_display": "节能器〔空调自然冷却语境〕", "definition_zh": "在室外条件适宜时，利用室外空气或经冷却塔等冷源冷却的水承担部分或全部冷负荷，以减少或避免机械制冷的装置及运行方式。空气侧和水侧的结构、启用条件及控制要求不同。", "scope_note": "", "name_basis": "国际金融公司EDGE用户指南3.0.a（2021）EEM20的中文标题就是“节能器”，同节同时列空气侧与水侧节能器，且目的与本词条自然冷却范围相同。不是仅凭某一个子类的名称外推泛称。AMCA出版物511-21中文4.1.2另直接定义“空气节能器”。", "evidence_note": "国际金融公司EDGE官方中文指南直接给出上位名称及空气侧、水侧说明；AMCA中文出版物定义空气子类；维萨拉和江森自控官方中文资料互证。不是锅炉省煤器或制冷剂经济器的定义。", "category": "systems-controls"}, {"id": "edge-computing", "en": "Edge computing", "zh_display": "边缘计算", "definition_zh": "在靠近物或数据源的一侧组合网络、计算、存储和应用能力，就近提供服务的计算方式，可与云端协作，不必限定在建筑内部。", "scope_note": "", "name_basis": "GB/T41780.1-2022正式题名采用“边缘计算”；具体解释据工业互联网产业联盟2019版《工业互联网术语和定义》第12项。该报告由信通院及政府网站发布，不冒充政府制定或国标全文。", "evidence_note": "工业互联网产业联盟中文术语报告（2019版）概述，另有现行国标名称证据", "category": "data-software"}, {"id": "electrification", "en": "Electrification", "zh_display": "电气化", "definition_zh": "以电力及电力驱动技术替代原先使用其他燃料的设备或过程。建筑可涉及供暖、热水和烹饪；减排效果取决于电源及系统效率。", "scope_note": "", "name_basis": "IEA官方中文报告使用“电气化”，可核对其建筑及供热语境；不自行把专名扩为“建筑终端用能电气化”。", "evidence_note": "国际能源署中文用法；英文政府释义补充", "category": "energy-sustainability"}, {"id": "embodied-carbon", "en": "Embodied carbon", "zh_display": "隐含碳排放", "definition_zh": "与建筑材料及建造过程相关的温室气体排放，可涵盖生产、运输、施工、维修更换及寿命末期处理，具体模块按评估体系确定。", "scope_note": "", "name_basis": "RESET中文使用“隐含碳”；RICS用于补充完整生命周期边界。“隐含碳”不等于材料内物理储存的碳。", "evidence_note": "官方中文用法或相关概念＋一手技术资料综合概述，非统一中文定义条文", "category": "energy-sustainability"}, {"id": "energy-audit", "en": "Energy audit", "zh_display": "能源审计", "definition_zh": "按有关法规和标准，对用能活动进行检验、核查和分析，评价用能水平、管理状况及节能潜力，为改进提供依据。", "scope_note": "", "name_basis": "采用国家节能中心直接发布的中文解释；建筑内容为适用范围说明。", "evidence_note": "国家节能中心中文定义概述", "category": "energy-sustainability"}, {"id": "energy-baseline", "en": "Energy baseline", "zh_display": "能源基准〔EnB〕", "definition_zh": "用于比较能源绩效的定量参照，依据规定期间的数据和条件建立；当气候、产出或使用条件变化时，可能需要归一化或调整。", "scope_note": "", "name_basis": "国家标准目录确认中文名称；介绍为相关标准框架概述，不作为标准条文原文。", "evidence_note": "国标名称＋官方中文解读；定义条文未直接取得", "category": "energy-sustainability"}, {"id": "energy-flexibility", "en": "Energy flexibility", "zh_display": "能源灵活性〔施耐德、西门子中文用语〕", "definition_zh": "建筑在满足使用者需求及运行约束的前提下，根据当地气候、能源价格及能源网络要求，管理和调节自身能源需求与供给的能力，可通过负荷移时或调节、储能和现场能源生产等方式实现。", "scope_note": "", "name_basis": "施耐德中国官网在“物联网与能源”中直接使用“能源灵活性”；西门子2022中文技术报告亦使用该词，已具可采用的头部企业中文命名证据。技术定义保持IEA建筑能源供需管理的广义范围，不限电力。另检得CABEE2024征求稿曾列建筑能源灵活性，但已发布T/CABEE121—2025术语改为建筑电力灵活性，不以旧草案冒称现行广义标准。", "evidence_note": "施耐德中国官网及西门子公开中文技术资料证明名称；建筑概念定义据IEA EBC Annex82原始说明整理", "category": "energy-sustainability"}, {"id": "energy-management-system", "en": "Energy management system", "zh_display": "能源管理系统；能源管理体系〔须区分语境〕", "definition_zh": "技术系统用于采集、分析、报告及可能控制用能；ISO 50001语境的能源管理体系则管理组织能源方针、目标和过程，两者不能等同。", "scope_note": "", "name_basis": "厂商/开源项目使用“能源管理系统”；GB/T 23331—2020等同ISO 50001:2018，正式中文名称是“能源管理体系”。这是不同含义，不能混为一个统一译名。", "evidence_note": "中文产品技术说明与中文管理标准名称/范围的区分概述", "category": "systems-controls"}, {"id": "energy-performance-certificate", "en": "Energy Performance Certificate", "zh_display": "EPC；能源绩效证书〔IFRS／GRESB用语〕", "definition_zh": "按适用国家制度记录建筑能源性能及有关改进信息的证书；评定依据、等级和用途因法域与版本不同，不应一律定义为模型A—G评级。", "scope_note": "", "name_basis": "IFRS基金会中文行业指南使用“欧盟能源绩效证书（EPC）”，另一章节见“能源业绩证书”；台湾政府研究报告也使用“能源效率证书”。不能据此认定只有一个法定中文名。", "evidence_note": "标准制定及评价组织中文名称用法；特定德国制度中文说明", "category": "energy-sustainability"}, {"id": "energy-performance-of-buildings-directive", "en": "Energy Performance of Buildings Directive", "zh_display": "EPBD；建筑能效指令〔政府及IEA中文用语〕", "definition_zh": "欧盟规定建筑能源性能框架、最低要求、改造、证书及相关建筑系统要求的指令，具体义务依适用条款和成员国转置执行。", "scope_note": "", "name_basis": "商务部网站中文资料使用“建筑能效指令（EPBD）”；这是政府中文转述，未检得欧盟法律制定方的正式中文法令文本。", "evidence_note": "政府/国际组织中文名称及政策解释；欧盟英文法规补充", "category": "energy-sustainability"}, {"id": "energy-star", "en": "Energy Star", "zh_display": "能源之星〔ENERGY STAR〕", "definition_zh": "美国政府支持的自愿性能效标识计划，涵盖产品、住宅、商业建筑及工业等领域；建筑能效评分、专业核验与认证是相关但不同的程序。", "scope_note": "", "name_basis": "原稿单写EPA管理已不足反映2026状态。EPA和ENERGY STAR官方现说明DOE/EPA共同管理并按2026协议向DOE集中管理过渡；主定义改为稳定的美国政府支持计划，机构过渡放核注。", "evidence_note": "中文名称沿用既有政府用法；DOE/EPA当前官方状态说明和计划资料，释义为稳定概述", "category": "certifications-ratings"}, {"id": "energy-use-intensity", "en": "Energy use intensity", "zh_display": "能源使用强度；耗能密度〔不同政府中文用语〕", "definition_zh": "建筑全年耗能量除以对应建筑面积所得的强度指标；必须说明能源范围、现场或源头能耗及建筑面积口径。", "scope_note": "", "name_basis": "台湾内政部门《建筑物动态EUI标准计算规范》明确将Energy-use intensity对应“耗能密度EUI”；不再自行定名为“能源使用强度”。", "evidence_note": "政府中文名称及特定计算定义；EPA英文通用计算说明", "category": "energy-sustainability"}, {"id": "enocean", "en": "EnOcean", "zh_display": "EnOcean；易能森〔联盟用语〕", "definition_zh": "结合能量采集与超低功耗设计的无线技术体系，可利用按键、光照或温差等获取能量，减少开关与传感器对电池和布线的依赖。", "scope_note": "", "name_basis": "联盟中文资料使用“易能森”；EnOcean亦是组织及品牌名称，条目此处按无线技术理解。", "evidence_note": "制定／标准组织自身中文资料概述", "category": "protocols-standards"}, {"id": "environmental-product-declaration", "en": "Environmental Product Declaration", "zh_display": "环境产品声明〔EPD〕", "definition_zh": "依据生命周期评价等规定方法，以经核查的定量信息披露产品或服务环境影响的声明；比较时须核对规则、单位、边界和数据条件。", "scope_note": "", "name_basis": "上海经信委中文页面明确EPD也叫“Ⅲ型环境产品声明”；GB/T24025正式题名为“Ⅲ型环境声明”。", "evidence_note": "官方中文用法或相关概念＋一手技术资料综合概述，非统一中文定义条文", "category": "energy-sustainability"}, {"id": "eu-taxonomy", "en": "EU Taxonomy", "zh_display": "欧盟可持续金融分类方案（EU Taxonomy）", "definition_zh": "欧盟识别环境可持续经济活动的分类制度，结合实质贡献、不造成重大损害、最低保障及技术筛选标准判定，非整栋建筑认证。", "scope_note": "", "name_basis": "欧委会发布的IPSF双语FAQ用欧盟可持续金融分类方案，证据高于政府转述；不是欧盟法律的法定中文文本。", "evidence_note": "欧委会网站正式发布的IPSF中英FAQ中文用语；非法定中文法律文本；法律内容仍核正式语言法规", "category": "certifications-ratings"}, {"id": "ev-charging", "en": "EV charging", "zh_display": "电动汽车充电", "definition_zh": "通过充电设备向电动汽车补充电能的过程及相关设施服务。建筑应用还需协调供配电容量、充电设备和负荷管理。", "scope_note": "", "name_basis": "GB/T 43332—2023使用电动汽车传导充放电术语，科技部公开资料讨论传导充电与无线充电；“电动汽车充电”为政府技术用语，完整通用定义未在目录页取得。", "evidence_note": "政府技术用法的概述；标准目录不替代全文定义", "category": "systems-controls"}, {"id": "facilities-management", "en": "Facilities management", "zh_display": "设施管理", "definition_zh": "在建成环境中整合人员、场所和过程，以改善人员生活质量、提高核心业务生产力的组织职能；设施、资产与服务的运行维护属于其活动范围。", "scope_note": "", "name_basis": "ISO委员会正式中文说明概述", "evidence_note": "ISO委员会正式中文说明支持概念主干；GB/T 36688—2026官方目录支持现行题名、实施日期及替代关系，未读2026标准定义全文。", "category": "fundamentals"}, {"id": "fan-coil-unit", "en": "Fan coil unit", "zh_display": "风机盘管机组〔FCU〕", "definition_zh": "由风机和换热盘管等组成，通过空气与冷水或热水换热，为空间供冷或供热的空调末端设备；新风供应须按系统另行配置。", "scope_note": "", "name_basis": "GB/T 19232—2019正式名称“风机盘管机组”；WS 696—2020第3.5—3.6条说明水介质末端与新风的关系（历史疫情标准仅用于术语核对）。", "evidence_note": "中文产品标准名称与卫生标准相关系统释义的概述", "category": "systems-controls"}, {"id": "fault-detection-and-diagnostics", "en": "Fault detection and diagnostics", "zh_display": "故障检测与诊断〔FDD〕", "definition_zh": "利用运行数据、规则或模型识别异常，并判断故障原因、影响及可能纠正措施的方法或系统；AFDD特指自动化实现。", "scope_note": "", "name_basis": "政府网站项目说明出现“故障檢測與診斷”；香港绿建会指南正式用“自動故障檢測和診斷（AFDD）”。前者为项目技术用语，后者为自动化子类，不是同一通用标准定义。", "evidence_note": "官方中文内容有据概述（范围及版本见文）", "category": "systems-controls"}, {"id": "fire-alarm-system", "en": "Fire alarm system", "zh_display": "火灾自动报警系统", "definition_zh": "探测火灾特征、发出报警，并为疏散、防止火势蔓延及启动相应消防设备提供控制或指示的系统。", "scope_note": "", "name_basis": "GB 50116—2013正式使用“火灾自动报警系统”；Fire alarm system国际泛称与该中国标准具体系统边界需分别说明。", "evidence_note": "中文工程建设标准定义的概述", "category": "systems-controls"}, {"id": "fit-out", "en": "Fit-out", "zh_display": "装修工程〔香港政府用语〕", "definition_zh": "使内部处所适合预定用途而进行的装修及相应设施配置。Cat A、Cat B是特定租赁市场的交付类别，具体范围由合同确定。", "scope_note": "", "name_basis": "政府中文用法及项目要求概述", "evidence_note": "政府中文用法及项目要求概述", "category": "fundamentals"}, {"id": "fitwel", "en": "Fitwel", "zh_display": "Fitwel认证", "definition_zh": "以实证研究为基础，通过建筑和场所的设计及运营策略改善使用者和社区健康福祉的评价与认证体系，具体要求依评分卡和版本确定。", "scope_note": "", "name_basis": "名称只采用可核来源实际用词；官方中文使用“Fitwel”“健康建筑认证”；不自行翻译该品牌名。", "evidence_note": "制定组织中文认证说明概述", "category": "certifications-ratings"}, {"id": "global-warming-potential", "en": "Global warming potential", "zh_display": "全球增暖潜势〔GWP；IPCC AR6用语〕", "definition_zh": "在指定时间跨度内，单位质量某温室气体造成的累积辐射强迫，相对等质量二氧化碳的比值，用于换算二氧化碳当量。", "scope_note": "", "name_basis": "GHGProtocol正式中文词汇表“全球升温潜势”，IPCCAR6中文术语表“全球增暖潜势”，SBTi中文术语表“全球变暖潜能值”；均需注明来源而非强选唯一译名。", "evidence_note": "制定组织中文术语表与IPCC中文定义概述", "category": "energy-sustainability"}, {"id": "green-star", "en": "Green Star", "zh_display": "Green Star", "definition_zh": "GBCA管理的建筑环境可持续性评级及认证体系，涵盖建筑、装修、社区和运行等不同工具；其他国家本地工具须按各自方案识别。", "scope_note": "", "name_basis": "未核得GBCA制定方独立正式中文专名，保留Green Star；新增台湾建研所2023年政府公开研究报告中的实质中文制度介绍。", "evidence_note": "补得政府公开研究中的中文概念介绍；仍未找到GBCA自行发布的正式中文完整定义。", "category": "certifications-ratings"}, {"id": "greenwashing", "en": "Greenwashing", "zh_display": "漂绿", "definition_zh": "通过夸大、模糊、选择性披露或误导性标签，使公众对企业、产品或活动的环境表现形成优于实际情况的印象。", "scope_note": "", "name_basis": "联合国官方中文用语为“漂绿”。", "evidence_note": "联合国中文说明概述", "category": "certifications-ratings"}, {"id": "gresb", "en": "GRESB", "zh_display": "GRESB", "definition_zh": "由投资者主导的实物资产ESG基准体系，通过标准化并经验证的数据对房地产及基础设施投资表现作比较；不同评估对象和模块须分别识别。", "scope_note": "", "name_basis": "新增GRESB官方2024中文版《房地产标准和参考指南》，第3页使用“GRESB房地产评级”；2016版用“GRESB房地产评估”。GRESB机构品牌仍保留英文，两种产品名称均须标明版本。", "evidence_note": "制定组织正式中文介绍，2024版与历史2016版分开", "category": "certifications-ratings"}, {"id": "grid-carbon-intensity", "en": "Grid carbon intensity", "zh_display": "电网碳排放强度〔Google Cloud中文技术文档用语〕", "definition_zh": "指定电网、地区和时段内，每单位电量所对应的碳排放量，常以gCO₂e/kWh等表示。应注明发电或用电口径、时间尺度、平均或边际方法，以及是否包含其他生命周期排放；平均电网强度不等于边际排放强度。", "scope_note": "", "name_basis": "Google Cloud官方中文文档直接写“每小时电网碳排放强度数据”，对应同页英文hourly grid carbon emission intensity data，并说明其仅含发电排放、排除其他生命周期阶段；已不必笼统保留英文。名称可用，但不能把Google特定数据边界推广为所有电网碳强度数据，也不能把平均、边际、基于位置和基于市场的指标混为同一数值。", "evidence_note": "Google Cloud同一技术文档中英直接对应名称及计算说明；生态环境部中文文件提供相关国内术语及适用背景", "category": "energy-sustainability"}, {"id": "grid-congestion", "en": "Grid congestion", "zh_display": "电网阻塞", "definition_zh": "电网传输能力或安全运行约束不足以容纳预期电力潮流的受限状态，可能需要调整发电、用电或交易安排。", "scope_note": "", "name_basis": "官方文件确认“电网阻塞”名称及安全约束语境；不是简单的全国电力短缺。", "evidence_note": "官方中文用法或相关概念＋一手技术资料综合概述，非统一中文定义条文", "category": "energy-sustainability"}, {"id": "grid-interactive-efficient-building", "en": "Grid-interactive efficient building", "zh_display": "GEB；电网交互式节能建筑〔RMI用语〕", "definition_zh": "结合能效、联网控制和能源灵活性，持续协调建筑与分布式能源运行，在满足使用需求的同时为电网提供可调节资源的建筑。", "scope_note": "", "name_basis": "RMI自己发布的中文研究报告使用“电网交互式节能建筑（Grid-interactive Efficient Building, GEB）”；不是DOE正式中文定名。", "evidence_note": "研究组织中文名称和解释；DOE英文原始定义", "category": "energy-sustainability"}, {"id": "healthcare-facility", "en": "Healthcare facility", "zh_display": "卫生保健设施〔WHO用语〕", "definition_zh": "提供诊断、治疗、护理或其他卫生保健服务的设施和场所；中国“医疗卫生建筑”的工程分类范围还可包括公共卫生、教学科研及辅助用房。", "scope_note": "", "name_basis": "WHO正式中文名称＋中文工程标准局部对应", "evidence_note": "WHO正式中文名称＋中文工程标准局部对应", "category": "building-types"}, {"id": "heat-pump", "en": "Heat pump", "zh_display": "热泵", "definition_zh": "利用外部输入能量将热量从低温环境转移至高温环境的设备或系统，可用于供暖和热水，部分系统能反向供冷。", "scope_note": "", "name_basis": "按政府中文技术说明概述；性能取决于热源温度、供水温度和工况，不提供固定通用COP。", "evidence_note": "官方中文用法或相关概念＋一手技术资料综合概述，非统一中文定义条文", "category": "energy-sustainability"}, {"id": "heat-recovery", "en": "Heat recovery", "zh_display": "热回收", "definition_zh": "将原本排走或废弃的热能经换热等方式回收利用，以减少后续加热或冷却需求；带热回收机械通风只是其中一种应用。", "scope_note": "", "name_basis": "大金中文资料及北京DB11/T 2240—2024第7.2节使用“热回收/排风热回收”；这是通风应用，Heat recovery在其他设备/水系统中的范围更广。", "evidence_note": "中文技术资料与地方标准具体应用的概述", "category": "systems-controls"}, {"id": "higher-education-building", "en": "Higher education building", "zh_display": "高等院校建筑〔标准类别用语〕", "definition_zh": "高等教育机构用于教学、研究及相关服务的建筑。本词条按院校归属合列的图书馆、宿舍、办公等设施，在用途、能耗或专业设计标准中可能另行分类。", "scope_note": "", "name_basis": "GB50763—2012第8.3.1条及深圳SJG103—2021第8.3.9条直接将“高等院校建筑”列为教育建筑类别，不是由“高等院校”自行拼接。可采用此有标准出处的名称；标准条款的教育建筑分类不能代替所有校内单体的用途分类。", "evidence_note": "已发布国家标准和政府发布地方标准正文直接使用“高等院校建筑”；名称有标准依据，此处释义为建筑用途概述，不是该标准独立定义条文。", "category": "building-types"}, {"id": "hotel", "en": "Hotel", "zh_display": "旅馆", "definition_zh": "为宾客提供住宿，可同时提供餐饮、会议、健身娱乐等部分或全部配套服务的建筑或设施，通常包括客房、公共及辅助部分。", "scope_note": "", "name_basis": "中文标准条文概述", "evidence_note": "中文标准条文概述", "category": "building-types"}, {"id": "hvac", "en": "HVAC", "zh_display": "供暖、通风与空气调节〔HVAC〕", "definition_zh": "供暖、通风及空气调节工程领域的合称，用于调节室内温度、湿度、空气流动和空气质量等条件，常简称“暖通空调”。", "scope_note": "", "name_basis": "GB/T 50155—2015题名为《供暖通风与空气调节术语标准》；AKM中文技术页直接用“暖通空调（HVAC）”。名称有据，但未把目录页题名当作该合称完整定义。", "evidence_note": "中文标准领域名称与厂商中文技术介绍的综合概述", "category": "systems-controls"}, {"id": "hybrid-working", "en": "Hybrid working", "zh_display": "混合工作", "definition_zh": "结合现场面对面工作与远程非现场工作的安排，工作地点和时间可按组织制度固定或灵活配置，不要求固定比例。", "scope_note": "", "name_basis": "厂商正式中文解释概述", "evidence_note": "厂商正式中文解释概述", "category": "fundamentals"}, {"id": "iec-62443", "en": "IEC 62443", "zh_display": "IEC 62443", "definition_zh": "工业自动化和控制系统网络安全标准系列，涉及资产所有者、服务提供者、系统和组件等层面的要求及过程，需按分部分声明符合性。", "scope_note": "", "name_basis": "名称只采用可核来源实际用词；中文主标题依据国内等同采用的第4-2部分；不同分部分的正式标题可能不同，不能把整个系列当作一个证书或一个条文。", "evidence_note": "国内采标中文名称＋ISA英文一手说明的中文概述", "category": "certifications-ratings"}, {"id": "indoor-air-quality", "en": "Indoor air quality", "zh_display": "室内空气质量〔IAQ〕", "definition_zh": "建筑室内空气的状况，应按适用标准评价相关物理、化学、生物及放射性指标；单项CO₂、PM₂.₅或TVOC读数不足以代表整体质量。", "scope_note": "", "name_basis": "GB/T18883—2022正式名称《室内空气质量标准》，第3.1条定义的是“室内空气质量指标”，不是本轮自造一般IAQ定义。", "evidence_note": "中文国家标准评价范围与指标的概述", "category": "health-occupancy"}, {"id": "industrial-building", "en": "Industrial building", "zh_display": "工业建筑", "definition_zh": "以工业性生产为主要功能的建筑，按相应分类还可包括动力、储运及生产辅助建筑，应依主要用途及适用规范判断。", "scope_note": "", "name_basis": "中文标准条文概述", "evidence_note": "中文标准条文概述", "category": "building-types"}, {"id": "industry-foundation-classes", "en": "Industry Foundation Classes", "zh_display": "工业基础类〔IFC〕", "definition_zh": "由buildingSMART维护的开放建筑及基础设施信息数据模式，表达对象、属性、关系和相关过程，支持BIM信息交换与共享。", "scope_note": "", "name_basis": "中文名称不只是2026征求意见稿用语：已发布GB/T25507—2010题名为《工业基础类平台规范》，交通运输部公开技术文本亦明列“工业基础类（Industry Foundation Class，IFC）”。旧版标准与当前IFC版本须区分，不能用2010版冒充新版完整技术内容。", "evidence_note": "已发布国家标准题名及政府技术文本双语名称；当前数据模式范围据制定方英文资料概述", "category": "protocols-standards"}, {"id": "interoperability", "en": "Interoperability", "zh_display": "互操作性", "definition_zh": "两个或多个系统、设备或组件能够交换信息或服务，并有效使用交换内容协同工作的能力。连接、格式和语义理解属于不同层面。", "scope_note": "", "name_basis": "国际标准组织正式中文报告概述", "evidence_note": "国际标准组织正式中文报告概述", "category": "fundamentals"}, {"id": "iot", "en": "IoT", "zh_display": "物联网〔IoT〕", "definition_zh": "将感知或控制设备、通信网络和信息处理结合，使物理对象、人员及信息资源连接并形成应用的技术与系统体系。", "scope_note": "", "name_basis": "现行GB/T33745-2025正式采用“物联网”，2025-12-01实施、替代2017版；旧生态环境行业标准的2017定义不作新版定义证据。", "evidence_note": "现行国标名称；政府历史定义／制造商技术资料的中文概述", "category": "data-software"}, {"id": "iso-19650", "en": "ISO 19650", "zh_display": "ISO 19650", "definition_zh": "使用BIM开展建成资产信息管理的国际标准系列，规定生命周期内的信息需求、职责、组织与交换，不仅是三维模型制作规范。", "scope_note": "", "name_basis": "保留制定方原名／标准编号；中文说明是应用或范围描述，不自行拼接成正式中文专名。中文描述依据BSI官方中文课程说明；ISO 19650为多部分系列，应按具体部分与版次引用，不能当作单一软件协议，未将中文描述宣称为ISO发布的完整中文题名。", "evidence_note": "BSI官方中文说明＋ISO英文范围的中文概述", "category": "protocols-standards"}, {"id": "iso-50001", "en": "ISO 50001", "zh_display": "ISO 50001能源管理体系标准", "definition_zh": "规定组织建立、实施、保持和改进能源管理体系的要求，以持续改善能源绩效；采用标准不必然要求认证，ISO本身不发认证证书。", "scope_note": "", "name_basis": "中文名称参考等同采用ISO 50001:2018的中国国家标准；与建筑设备软件型EMS应区别。", "evidence_note": "采标官方中文解读与ISO英文说明概述", "category": "certifications-ratings"}, {"id": "itot-convergence", "en": "IT/OT convergence", "zh_display": "IT／OT融合", "definition_zh": "使处理信息的IT系统与监测、控制物理设备和过程的OT系统连接协同，以支持运行分析及业务管理；融合不表示取消必要的隔离与权限控制。", "scope_note": "", "name_basis": "官方中文技术资料使用“IT／OT融合”；OT中文亦有“操作技术”等译法，本表依IBM中文资料采用“运营技术”。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "data-software"}, {"id": "knx", "en": "KNX", "zh_display": "KNX", "definition_zh": "面向住宅和楼宇自动化的开放通信及控制标准体系，用于照明、遮阳、供暖和通风等设备集成，具体介质和功能依实现确定。", "scope_note": "", "name_basis": "保留制定方原名／标准编号；中文说明是应用或范围描述，不自行拼接成正式中文专名。KNX为官方名称；“住宅与楼宇控制”是应用范围表述，不将其扩写为未经核实的中文品牌全称。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "protocols-standards"}, {"id": "laboratory", "en": "Laboratory", "zh_display": "实验室〔建筑空间／设施语境〕", "definition_zh": "开展实验教学、科学研究、技术研发、检验检测等活动的专用场所及配套附属空间，可构成一栋建筑或建筑的一部分；通风、安全和环境要求应依活动、对象及风险确定。", "scope_note": "", "name_basis": "旧实验用房是GB50504办公科研章节的特定用房概念，作本泛称主名偏窄。新增北京市正式地方标准直接列实验室/laboratory并覆盖教学、科研、研发及检验检测场所，更适合作主名和场所定义；不混用ISO17025的机构定义。", "evidence_note": "政府发布地方标准直接实验室/laboratory名称及场所定义；不同活动的安全要求另按规范，非把组织认可定义当空间定义", "category": "building-types"}, {"id": "large-language-model", "en": "Large language model", "zh_display": "大语言模型（LLM；亦称大型语言模型）", "definition_zh": "基于大规模语料训练、通常具有较大参数规模的语言模型，通过学习语言规律和上下文关系，支持语言理解、生成、摘要、翻译和问答等任务。在建筑软件中可用于文档查询、告警或工单摘要以及建筑数据的自然语言交互。部分模型还可扩展处理图像、音频等模态，具体能力依模型和应用而定。", "scope_note": "不设置跨体系固定参数量门槛，不硬限单一架构或训练目标；LLM不等同全部生成式AI、基础模型或完整智能体系统。", "name_basis": "大语言模型有现行行业标准中文题名及范围依据；大型语言模型见微软官方中文技术资料。保留两个已有依据的译名，不宣称存在唯一统一中文译名。", "evidence_note": "依据官方中文技术资料与原站建筑应用说明综合编写；不是某一标准定义的逐字引文。", "category": "ai"}, {"id": "leak-detection", "en": "Leak detection", "zh_display": "漏水检测", "definition_zh": "利用点式、线形传感器或适配的监测方法发现水或有关液体泄漏并发出信号；定位及自动关阀能力由具体系统决定。", "scope_note": "", "name_basis": "拓自达官方中文产品类别直接用“漏水检测”，与本页水泄漏场景对应；不是所有气体/液体泄漏检测的通用定义。", "evidence_note": "厂商中文产品技术说明的概述", "category": "systems-controls"}, {"id": "leed", "en": "LEED", "zh_display": "LEED；能源与环境设计先锋〔GBCI中文用语〕", "definition_zh": "USGBC开发的可持续性评级与认证体系，覆盖建筑、室内空间、社区和城市等项目，按所选方案审查先决条件、得分要求及相关性能证据。", "scope_note": "", "name_basis": "原定义仅写建筑可持续性体系，覆盖范围可补全。USGBC当前官网直接列新建/室内/运营/社区及城市，故主定义加入这些对象，不将LEED全品牌限于单栋建筑。", "evidence_note": "制定/认证组织中文名称；USGBC当前官网完整对象范围，释义为概述", "category": "certifications-ratings"}, {"id": "levels", "en": "Level(s)", "zh_display": "Level(s)框架〔DGNB中文用语〕", "definition_zh": "欧盟自愿建筑可持续性报告框架，借助核心指标和现有标准组织生命周期证据，并联系环境政策目标；本身不颁发建筑认证。", "scope_note": "", "name_basis": "DGNB正式中文标准集术语T&D_02使用“Level(s)框架”及“Level(S)可持续性评估绩效工具”；保留品牌写法Level(s)。", "evidence_note": "找到标准组织正式中文文件中的明确释义；它是DGNB的中文解释，不是欧盟发布的法定中文译文。", "category": "certifications-ratings"}, {"id": "library", "en": "Library", "zh_display": "图书馆", "definition_zh": "以收集、整理、保管、研究和利用文献信息为主要功能，通过借阅、咨询等方式提供服务的文化建筑。", "scope_note": "", "name_basis": "中文标准条文概述", "evidence_note": "中文标准条文概述", "category": "building-types"}, {"id": "life-cycle-assessment", "en": "Life cycle assessment", "zh_display": "生命周期评价〔LCA〕", "definition_zh": "汇编并评价产品系统生命周期中的输入、输出及潜在环境影响的方法，通常包括目标和范围、清单分析、影响评价及结果解释。", "scope_note": "", "name_basis": "中文名称依据国家标准；定义依据ISO一手术语概述，非宣称已取得中文标准全文。", "evidence_note": "国标中文名称＋ISO英文一手释义的中文概述", "category": "energy-sustainability"}, {"id": "lighting-control-system", "en": "Lighting control system", "zh_display": "照明控制系统", "definition_zh": "通过开关、调光器、传感器、控制器及控制逻辑，调节照明开闭与光输出，可采用时程、场景、人员、天然光或人工控制。", "scope_note": "", "name_basis": "北京DB11/T2240—2024第6.1.10使用“室内照明控制系统”；ABB官方中文用“照明控制”。有地方标准中的名称和功能用法，未取得独立通用国标术语定义。", "evidence_note": "地方标准中文功能要求与厂商中文技术说明的概述", "category": "systems-controls"}, {"id": "living-building-challenge", "en": "Living Building Challenge", "zh_display": "Living Building Challenge", "definition_zh": "Living Future推动再生建成环境的标准及认证体系，按相应路径评价场所、水、能源、健康、材料、公平和美等主题，并要求相关实际运行证明。", "scope_note": "", "name_basis": "新增政府公开中文用法：台湾建研所2024委托报告PDF第45页（印刷25页）列“生活建筑挑战”；建研所2020简讯用“居住建筑挑战”。不同用法不能选一个冒称ILFI统一正式译名，仍保留英文。", "evidence_note": "政府中文资料仅名称用法；制定组织英文定义的中文概述", "category": "certifications-ratings"}, {"id": "lonworks", "en": "LonWorks", "zh_display": "LonWorks", "definition_zh": "连接楼宇及工业控制设备的分布式控制网络技术体系，相关标准规定协议、通信信道、设备互操作及网络管理等内容。", "scope_note": "", "name_basis": "国家标准历史文件题名使用“控制网络LONWORKS技术规范”，专名仍为LONWORKS；保留LonWorks。", "evidence_note": "未核得同范围正式中文定义；另列外文一手资料的中文概述", "category": "protocols-standards"}, {"id": "lorawan", "en": "LoRaWAN", "zh_display": "LoRaWAN", "definition_zh": "面向物联网的开放低功耗广域网标准，支持小数据量设备通过网关和网络服务器连接应用；LoRa物理层与LoRaWAN协议不是同一概念。", "scope_note": "", "name_basis": "LoRa联盟自己发布的中文新闻稿一贯保留LoRaWAN，不能把“低功耗广域网”这一技术类别名称当作其独立中文专名。", "evidence_note": "官方中文内容有据概述（范围及版本见文）", "category": "connectivity"}, {"id": "low-temperature-heating", "en": "Low-temperature heating", "zh_display": "低温供暖", "definition_zh": "采用较低供热温度满足建筑热需求的供暖方式，常与热泵、低温热源及较大末端换热面积结合；温度界限须依具体系统和标准确定。", "scope_note": "", "name_basis": "新增地方标准明确用语低温供暖，可撤销完全无中文用法的保留；35—55℃只是特定系统常见范围，不是本词统一定义。", "evidence_note": "官方地方标准中的明确中文用法；广义概念释义据IEA一手资料综合，并非该标准独立术语条文", "category": "energy-sustainability"}, {"id": "m-bus", "en": "M-Bus", "zh_display": "M-Bus", "definition_zh": "用于远程读取水、热、燃气、电等消耗计量仪表的通信技术；有线形式常采用两线总线，另有无线M-Bus。", "scope_note": "", "name_basis": "保留M-Bus。现行GB/T17215.673-2021正式题名保留M-Bus；陕西省知识产权局发布的产业专利导航研究有“户用仪表总线（M-Bus）”，是政府研究用法而非制定组织正式译名。", "evidence_note": "官方中文内容有据概述（范围及版本见文）", "category": "protocols-standards"}, {"id": "machine-learning", "en": "Machine learning", "zh_display": "机器学习〔ML〕", "definition_zh": "计算系统通过数据或经验学习模式、建立或调整模型并改善任务表现的过程及方法，可用于预测、分类等任务；不同学习方式对人工标注的要求不同。", "scope_note": "", "name_basis": "将术语性较强的“功能单元取得知识技能”整理为适合建筑文档的技术释义；保留数据、经验、性能改进和多种学习方式，非逐字标准引文。", "evidence_note": "政府中文监管指南术语与制造商技术资料概述", "category": "data-software"}, {"id": "master-systems-integrator", "en": "Master systems integrator", "zh_display": "主系统集成商〔Tridium用语〕", "definition_zh": "负责跨系统集成策略的项目技术角色，统筹数据视图、接口、聚合、控制、分析及测试，使多厂商系统协同；不直接对应法定施工资质。", "scope_note": "", "name_basis": "原【参】词条继续复核（2026-11-05）。名称核查：Tridium中文官网明确对应“主系统集成商（MSI）”；这是技术厂商官方用语，不是中国法定资质名称。 释义核查：找到厂商自身的中文角色说明；其范围及效力限于该技术、业务语境。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "data-software"}, {"id": "material-passport", "en": "Material passport", "zh_display": "材料护照〔中瑞合作研究用语〕", "definition_zh": "记录材料、产品和组件特性及相关过程、健康安全信息的数据集合，用于支持生产、使用、拆卸、再利用及处理的生命周期追踪。", "scope_note": "", "name_basis": "原【参】词条继续复核（2026-11-05）。名称核查：中瑞零碳建筑合作项目2025年中文报告明确将Material Passports对应“材料护照”。 释义核查：找到有双边政府项目背景的中文研究说明及缩略词表；不是国家标准中的统一术语。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "data-software"}, {"id": "matter", "en": "Matter", "zh_display": "Matter", "definition_zh": "连接标准联盟维护的基于IP的物联网应用层开放标准，支持跨品牌设备和生态互操作，可使用Thread、Wi-Fi及以太网等网络承载。", "scope_note": "", "name_basis": "CSA制定组织直接采用Matter专名；本轮不单凭matter.cn自称中文官方网站认定其组织治理身份，亦不把描述性中文拼成正式品牌名称。", "evidence_note": "制定组织英文定义中文概述；中文辅助页不作唯一官方归属证据", "category": "protocols-standards"}, {"id": "measurement-and-verification", "en": "Measurement and verification", "zh_display": "测量和验证〔M&V〕", "definition_zh": "为核实和报告节能措施成果而开展计划、测量、数据收集及分析，通常比较经适当条件调整的基准与实施后用能。", "scope_note": "", "name_basis": "中文命名依据国家标准标题；方法介绍依据IPMVP发布机构EVO。", "evidence_note": "官方中文用法或相关概念＋一手技术资料综合概述，非统一中文定义条文", "category": "energy-sustainability"}, {"id": "mixed-use-development", "en": "Mixed-use development", "zh_display": "混合用途发展〔香港规划用语〕", "definition_zh": "在同一项目、场址或建筑中组合相容的不同用途，例如住宅、办公、商业及酒店，空间组织和规划条件依地区及项目确定。", "scope_note": "", "name_basis": "政府规划文件中文用法概述", "evidence_note": "政府规划文件中文用法概述", "category": "building-types"}, {"id": "modbus", "en": "Modbus", "zh_display": "Modbus协议", "definition_zh": "工业设备交换过程数据的应用层协议，规定功能码、寻址和数据格式，可由串行链路或TCP/IP承载；另有基于TLS和证书的安全扩展。", "scope_note": "", "name_basis": "现行GB/T 19582.1-2008正式题名明确使用“Modbus协议”“Modbus应用协议”；保留专名Modbus，不另造音译。", "evidence_note": "官方中文内容有据概述（范围及版本见文）", "category": "protocols-standards"}, {"id": "model-predictive-control", "en": "Model predictive control", "zh_display": "模型预测控制〔MPC〕", "definition_zh": "利用模型预测系统未来响应，在目标与约束下确定控制动作并滚动更新的控制方法；显式实现可调用预先求解的控制律。", "scope_note": "", "name_basis": "MathWorks官方中文技术页直接用“模型预测控制（MPC）”并解释优化；另有政府应用用法，但未据此称国标统一术语。", "evidence_note": "算法工具开发组织官方中文技术说明的概述", "category": "systems-controls"}, {"id": "monitoring-based-commissioning", "en": "Monitoring-based commissioning", "zh_display": "基于监测的调试〔USGBC用语〕", "definition_zh": "持续采集和评估系统运行数据，按计划识别性能偏差、采取纠正措施并验证结果的调试过程，包含监测、职责、异常处理及维护安排。", "scope_note": "", "name_basis": "USGBC正式中文LEED v4文件采用“基于监测的调试”，可替换前版“基于监测的调适”的参考译称。", "evidence_note": "USGBC正式中文LEED v4文件采用“基于监测的调试”，可替换前版“基于监测的调适”的参考译称。", "category": "fundamentals"}, {"id": "mqtt", "en": "MQTT", "zh_display": "MQTT", "definition_zh": "轻量的发布／订阅消息传输协议，由消息代理按主题转发发布者和订阅者之间的消息，适合资源受限的物联网通信。", "scope_note": "", "name_basis": "保留制定方原名／标准编号；中文说明是应用或范围描述，不自行拼接成正式中文专名。中文官方技术资料直接使用MQTT；不以历史缩写展开代替当前正式协议名称。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "protocols-standards"}, {"id": "multifamily-residential", "en": "Multifamily residential", "zh_display": "多户住宅〔政府中文用语〕", "definition_zh": "含多个独立住宅单元的住宅物业；可为一栋或多栋建筑，户数门槛及统计边界依方案确定，不以楼层高低划分。", "scope_note": "", "name_basis": "美国波特兰市政府中文资料采用“多户住宅”，对应Multifamily类物业；可确认政府中文用法。", "evidence_note": "美国波特兰市政府中文资料采用“多户住宅”，对应Multifamily类物业；可确认政府中文用法。", "category": "building-types"}, {"id": "nabers", "en": "NABERS", "zh_display": "NABERS；澳大利亚国家建筑环境评级系统〔IFRS用语〕", "definition_zh": "澳大利亚建筑环境绩效评级体系。运行类评级使用实际数据评价能源、水、废弃物及室内环境，另有前期隐含碳评级等工具；不同类别的数据要求、核算边界及地区实施方案分别确定。", "scope_note": "", "name_basis": "NABERS已不宜只定义为运行数据评级。官方已有Embodied Carbon评级与2026年2月v2.1规则；应区分运行类评级与隐含碳等工具，不把全体系限定为运行能耗。", "evidence_note": "IFRS/GRESB中文名称；NABERS官方运行及隐含碳评级工具说明，非全体系统一运行数据方法", "category": "certifications-ratings"}, {"id": "natural-ventilation", "en": "Natural ventilation", "zh_display": "自然通风", "definition_zh": "不使用通风机械，依靠风压及室内外温差形成的热压实现空气交换的方式；自然与机械相结合时应另称复合或混合模式通风。", "scope_note": "", "name_basis": "依据《供暖通风与空气调节术语标准》；介绍为概述。", "evidence_note": "国家标准中文条文概述", "category": "energy-sustainability"}, {"id": "nb-iot", "en": "NB-IoT", "zh_display": "窄带物联网〔NB-IoT〕", "definition_zh": "基于蜂窝网络、面向低速率大量设备连接的低功耗广域物联网技术；与LTE-M是不同技术，不能互作别称。", "scope_note": "", "name_basis": "工信部文件明确使用NB-IoT（窄带物联网），介绍结合官方技术文档。", "evidence_note": "政府中文名称＋行业组织／制造商中文技术概述", "category": "connectivity"}, {"id": "nearly-zero-energy-building", "en": "Nearly zero-energy building", "zh_display": "近零能耗建筑〔nZEB〕", "definition_zh": "能源性能很高、运行能源需求很低，并充分利用可再生能源的建筑。中国标准与欧盟指令对能耗、可再生能源和计算边界各有规定；欧盟定义要求很大程度上由可再生能源覆盖低能源需求，使用时须标明所依据的制度。", "scope_note": "", "name_basis": "近零能耗在中国标准与欧盟EPBD下要求不同，需明确框架；为避免首句只套欧盟，调整为跨制度概述。 独立复核后，将跨制度概述与欧盟“很大程度”覆盖能源需求的要求分开表述。", "evidence_note": "标准/政策名称明确；释义为跨制度综合概述，不能替代中国GB/T51350或欧盟EPBD各自条文", "category": "energy-sustainability"}, {"id": "neighbourhood-development", "en": "Neighbourhood development", "zh_display": "社区开发〔USGBC中文用语〕", "definition_zh": "在社区或街区尺度组织土地、建筑、街道、公共空间和基础设施的规划开发活动；通用活动与LEED ND认证应区分。", "scope_note": "", "name_basis": "制定组织正式中文用法及体系范围", "evidence_note": "制定组织正式中文用法及体系范围", "category": "building-types"}, {"id": "net-zero-carbon-building", "en": "Net zero carbon building", "zh_display": "净零碳建筑", "definition_zh": "在明确的核算边界和评价期间内，优先减少建筑相关温室气体排放，再按所采用框架规定的方法平衡剩余排放，使净排放达到零的建筑。须分别声明运行碳或全生命周期边界，以及可再生能源、清除和抵消的适用规则。", "scope_note": "", "name_basis": "原文在通用标题下只采用Architecture2030的运行能源口径，过窄；改为声明核算边界、期间和所采框架的有据综合定义。", "evidence_note": "制定组织官方中文名称；释义据多个一手框架综合，并非统一官方中文定义", "category": "energy-sustainability"}, {"id": "network-segmentation", "en": "Network segmentation", "zh_display": "网络分段", "definition_zh": "将网络划分为相互隔离或受控连接的部分，并规定部分之间的流量策略，以支持业务隔离、访问限制和故障影响控制。", "scope_note": "", "name_basis": "使用专业服务商官方中文定义，非宣称国家标准条文。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "connectivity"}, {"id": "occupancy-analytics", "en": "Occupancy analytics", "zh_display": "空间占用分析〔政府平台收录方案用语〕", "definition_zh": "利用传感、门禁或网络等资料，分析空间是否、何时及被多少人使用，形成占用情况、使用率和峰值等信息，支持空间配置及运行服务；设备数与实际人数须区别。", "scope_note": "", "name_basis": "政府智慧实验室同一方案中英页明确将Space Occupancy Analytics表述为空间占用分析，比仅引Juniper“占用率分析”更适合本词的广义空间使用分析。页面为供应商方案收录，不能据域名就称政府自行定义。", "evidence_note": "政府创新平台收录的供应商方案中文用语，非政府制定术语或统一国家标准", "category": "health-occupancy"}, {"id": "occupancy-sensor", "en": "Occupancy sensor", "zh_display": "占位传感器〔DALI联盟及国标用语〕", "definition_zh": "向应用控制器提供空间占位信息的输入设备，也可集成在应用控制器中。不同技术在运动、静止存在及人数检测方面能力不同，不能把占位检测、运动检测和人数统计等同。", "scope_note": "", "name_basis": "DALI联盟自身发布中英对照术语表，直接给出Occupancy sensor的名称和中文定义，已具备正式中文名称依据；应撤销过度保守的保留英文结论。跨行业使用时保留DALI语境提示。", "evidence_note": "DALI联盟推荐中英术语及中文释义；国家标准题名互证", "category": "systems-controls"}, {"id": "occupant-feedback", "en": "Occupant feedback", "zh_display": "建筑使用者反馈〔住建部技术指南用语〕", "definition_zh": "收集建筑使用者对舒适、空间及服务的意见，并用于发现问题、回应需求和改进运行，可使用调查、应用或现场反馈等方式。", "scope_note": "", "name_basis": "新增住建部2017《绿色建筑后评估技术指南（办公和商店建筑版）》1.0.2条文说明明确出现“建筑使用者反馈”，并将主观反馈和投入使用后的运行效果、满意度及建筑性能联系起来，已是同领域中文用法。可采用该词，不再仅借较窄USGBC“驻户满意度反馈”；指南针对办公和商店建筑，未声称制定了涵盖一切建筑的独立术语条文。", "evidence_note": "住建部已印发技术指南中的中文用语；指南正文来自公开镜像，发布身份用政府通知互证；释义为有据概述，非独立术语定义原文", "category": "health-occupancy"}, {"id": "occupant-privacy", "en": "Occupant privacy", "zh_display": "使用者隐私〔建研所智慧空间研究用语〕", "definition_zh": "在建筑系统收集、使用、共享或推断个人信息时保护使用者隐私，包括位置、身份和行为数据；需考虑最少收集、访问限制及保留周期。", "scope_note": "", "name_basis": "建研所《建筑简讯》张怡文专题《参加智慧科技应用信任、隐私及安全国际研讨会》第（三）节直接使用“使用者隐私”，描述感测器网络、建筑管理系统、第三方服务、资料共享及使用控制，已属本词的建筑数据隐私语境。可采用该来源限定中文用语，不必因为没有完整中英词典条目而保留英文。不能改写成该机构已制定Occupant privacy统一定义。", "evidence_note": "政府建筑研究机构自撰中文专题报道的同领域用语与数据共享说明；非独立术语标准的逐字定义", "category": "data-software"}, {"id": "ocpp", "en": "OCPP", "zh_display": "开放充电协议〔OCPP〕", "definition_zh": "开放充电联盟维护的充电站与中央充电管理系统之间的通信协议，支持计量、交易、远程管理及按版本规定的智能充电功能。", "scope_note": "", "name_basis": "联盟官网提供的中文译本明确使用“开放充电协议”，并署名翻译单位。该白皮书内容较早，版本状态另查联盟当前英文页，不沿用旧文“1.6为最新”的表述。", "evidence_note": "制定／标准组织自身中文资料概述", "category": "protocols-standards"}, {"id": "office-building", "en": "Office building", "zh_display": "办公建筑", "definition_zh": "用于办理行政事务及开展业务活动的建筑；单租户、多租户是经营和使用形式，办公室则是其中的办公房间。", "scope_note": "", "name_basis": "中文标准条文概述", "evidence_note": "中文标准条文概述", "category": "building-types"}, {"id": "opc-ua", "en": "OPC UA", "zh_display": "OPC统一架构〔OPC UA〕", "definition_zh": "OPC基金会制定的平台独立互操作架构，统一信息建模、数据访问、事件和方法等机制，并提供认证、加密、签名等安全能力。", "scope_note": "", "name_basis": "OPC中国官方中文页面采用“OPC统一架构”；安全能力是否启用仍取决于实际配置和实现。", "evidence_note": "制定／标准组织自身中文资料概述", "category": "protocols-standards"}, {"id": "openadr", "en": "OpenADR", "zh_display": "OpenADR", "definition_zh": "供公用事业、电网运营商、聚合商及能源系统交换需求响应、电价或相关能源管理信息的开放标准，建筑可据此按规则调整负荷。", "scope_note": "", "name_basis": "连接标准联盟与OpenADR联盟联合新闻稿的官网中文页保留OpenADR；没有在该页正式定名为“开放式自动需求响应”。", "evidence_note": "官方中文内容有据概述（范围及版本见文）", "category": "protocols-standards"}, {"id": "operational-carbon", "en": "Operational carbon", "zh_display": "运行碳排放", "definition_zh": "建筑运行阶段相关的温室气体排放。本词条主要采用运行能源口径，包括供暖、制冷、照明、热水及设备能耗等；RICS全生命周期评价还将运行用水的供水与污水处理排放列入运行碳（B7），应明确采用的核算边界。", "scope_note": "", "name_basis": "国内标准公开解读采用“建筑运行阶段碳排放”；具体核算范围须按所用标准。 第六轮名称维持，定义范围按本轮来源补充。", "evidence_note": "中国建筑运行能源口径与RICS第二版全生命周期运行能源/用水口径分别说明；释义为跨来源有据概述，非统一中文条文", "category": "energy-sustainability"}, {"id": "operational-technology-security", "en": "Operational technology security", "zh_display": "运营技术安全〔OT安全〕", "definition_zh": "保护直接监测或控制物理设备和过程的硬件、软件与网络，降低攻击、未经授权访问和运行中断风险，兼顾可用性和物理影响。", "scope_note": "", "name_basis": "中文名称依据IBM官方中文资料；“运营技术安全”在此主要指网络与信息安全，不能替代完整的机械、电气及消防安全管理。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "data-software"}, {"id": "paris-proof", "en": "Paris Proof", "zh_display": "Paris Proof", "definition_zh": "DGBC推动的与巴黎气候目标相容的建筑减碳路径，结合降低实际能源消耗和遵守建造、翻新碳预算；运行与材料指标使用不同方法。", "scope_note": "", "name_basis": "复查荷兰DGBC项目、词典及相关中文资料，未检得制定方正式中文专名或中文释义；保留Paris Proof。", "evidence_note": "未检得可直接对应的官方中文释义；下述技术核对据外文一手资料，不作为官方中文定义。", "category": "certifications-ratings"}, {"id": "passivhaus", "en": "Passivhaus", "zh_display": "被动房〔Passivhaus体系〕", "definition_zh": "PHI提出的性能标准及认证体系，通过高性能围护、气密性、减少热桥和高效通风等实现很低的供暖或供冷需求，同时保持舒适。", "scope_note": "", "name_basis": "机构中文资料使用“被动房”。泛称“被动式设计”或国内超低能耗建筑，不自动等同于达到PHI认证标准。", "evidence_note": "官方中文用法或相关概念＋一手技术资料综合概述，非统一中文定义条文", "category": "energy-sustainability"}, {"id": "peak-demand", "en": "Peak demand", "zh_display": "峰值需求", "definition_zh": "指定统计期间内的最高需求功率，通常为规定计量间隔平均功率的最大值；计费最大需量与瞬时峰值须区分。", "scope_note": "", "name_basis": "新增一手机构发布中英词汇表，peak demand可用峰值需求；计费最大需量仍依当地时间间隔和合同定义。", "evidence_note": "PURC基础设施监管知识体系所发布中英词汇表；并非中国国家计量或电价标准定义", "category": "energy-sustainability"}, {"id": "performance-gap", "en": "Performance gap", "zh_display": "性能差距〔中瑞零碳建筑合作项目中文用语〕", "definition_zh": "建筑在设计阶段的预测性能与投入使用后的实测表现之间的差距。讨论运行能耗时，应明确预测边界、实测指标以及气候和使用条件，不能将所有差异都归因于设备效率。", "scope_note": "", "name_basis": "新增中瑞零碳建筑合作项目2022双语信息手册，脚注10直接以“性能差距”对应performance gap并解释设计预测与使用阶段实测差异。版权页明列瑞士发展与合作署、住建部资助、intep和Skat实施及intep中国团队翻译。可采用来源限定名，不再全部保留英文。正文另一处出现“业绩差距”，名称以脚注明确定义及后文“性能差距”用法为据。", "evidence_note": "政府资助中瑞合作项目正式双语手册的中文名称及直接定义；不是中国国家术语标准或政府单独颁布的定义", "category": "fundamentals"}, {"id": "pid-control", "en": "PID control", "zh_display": "比例—积分—微分控制〔PID控制〕", "definition_zh": "依据测量值与设定值之间的偏差，将比例、积分和微分作用组合为控制输出，分别响应当前偏差、累计偏差及其变化趋势。", "scope_note": "", "name_basis": "NI官方中文技术页明确“比例-积分-微分（PID）控制”，2025-03-13更新。", "evidence_note": "技术开发商官方中文算法说明的概述", "category": "systems-controls"}, {"id": "pm25", "en": "PM2.5", "zh_display": "细颗粒物〔PM₂.₅〕", "definition_zh": "空气中按空气动力学当量直径划分的细颗粒物类别，通常简述为粒径小于或等于2.5微米。实际监测应采用标准规定的粒径选择特性与测量方法，2.5微米不表示仪器对每个颗粒都是理想的硬截断，也不同于PM₁₀。", "scope_note": "", "name_basis": "旧稿空气动力学直径≤2.5µm与国标惯用简述一致，不应简单判错；为防读者将其误作理想硬筛上限，补充标准采样切割特性与测量方法。新增正式HJ93—2026，而非2025征求稿。", "evidence_note": "国标中文类名及名义粒径简述；正式HJ93—2026补充采样切割特性，释义为综合概述", "category": "health-occupancy"}, {"id": "point-naming-convention", "en": "Point naming convention", "zh_display": "命名规则〔楼宇测控点语境，西门子用语〕", "definition_zh": "为建筑控制系统中的变量和测控点规定一致的名称构成、层级、缩写及编号规则，以识别工程、机组、设备和测量或控制对象；具体格式依项目及系统约定，不等同完整语义模型。", "scope_note": "", "name_basis": "新增西门子Logic Manager Desigo Essentials官方中文操作手册附录5“命名规则_1”，明确变量名及GPI变量名由工程、设备分类、机组、设备和点位构成，并给AHU_F1_1.SF_STA例。可采用原文已有“命名规则”并保留楼宇测控点语境限定；不自行扩写成来源中未出现的正式题名“点位命名规范”。", "evidence_note": "西门子官方中文操作手册的同范围命名规则及实施示例；不是统一国家术语标准或逐字中英词典条目", "category": "data-software"}, {"id": "post-occupancy-evaluation", "en": "Post-occupancy evaluation", "zh_display": "楼宇用后评估〔香港建筑署用语〕", "definition_zh": "建筑投入使用后，结合使用者意见和性能实测资料评价建筑及设施的实际效能，并将结果用于运行调校、管理改进和设计反馈。", "scope_note": "", "name_basis": "政府中文方法说明概述", "evidence_note": "政府中文方法说明概述", "category": "fundamentals"}, {"id": "power-over-ethernet", "en": "Power over Ethernet", "zh_display": "以太网供电〔PoE〕", "definition_zh": "利用以太网数据电缆在传输数据的同时向设备供电的技术；供电设备、受电设备、线路及功率等级须相互匹配。", "scope_note": "", "name_basis": "官方中文技术文档明确采用“以太网供电”。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "connectivity"}, {"id": "power-purchase-agreement", "en": "Power purchase agreement", "zh_display": "购电协议〔PPA〕", "definition_zh": "购电方与发电或售电方约定电力购买、支付及风险分配等事项的合同，可涉及化石或可再生能源；不一定要求电力实物直接送达买方。", "scope_note": "", "name_basis": "世界银行PPP资源中心中文页面明确使用“购电协议（PPA）”，并列出化石能源与可再生能源两类。", "evidence_note": "世界银行中文名称/范围；英文一手定义概述", "category": "energy-sustainability"}, {"id": "predictive-maintenance", "en": "Predictive maintenance", "zh_display": "预测性维护", "definition_zh": "结合设备状态、历史及实时数据，使用分析方法判断未来退化或故障并安排维护；区别于单纯按日历维护，也不完全等同状态维护。", "scope_note": "", "name_basis": "中文名称与说明依据IBM官方中文资料；预测不等于对故障时间的确定性保证。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "data-software"}, {"id": "private-5g", "en": "Private 5G", "zh_display": "5G专网／专用5G网络〔厂商中文用语〕", "definition_zh": "在特定区域为特定组织或用户提供专用业务服务的5G网络，可采用独立或与公网共享部分设施等部署方式；不等同Private LTE。", "scope_note": "", "name_basis": "中文官方用语存在“5G专网”“专用5G网络”“私有5G”等；本表同时保留前两种，不能仅据Private一词判断网络所有权与部署模式。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "connectivity"}, {"id": "project-haystack", "en": "Project Haystack", "zh_display": "Project Haystack", "definition_zh": "通过元数据标签、关系和数据交换约定表达物联网与楼宇数据含义的开源项目，范围包括语义数据模型及Web服务。", "scope_note": "", "name_basis": "项目官网正式提供Chinese Guide Specification下载，中文指南仍用Project Haystack，不另设中文项目名。", "evidence_note": "官方中文内容有据概述（范围及版本见文）", "category": "protocols-standards"}, {"id": "proptech", "en": "Proptech", "zh_display": "房地产科技", "definition_zh": "用于房地产开发、交易、租赁、资产管理及物业运营等环节的技术、数据和数字服务；智能建筑技术是其中涉及建筑实体运行的一部分。", "scope_note": "", "name_basis": "发布机构中文用法及研究概述", "evidence_note": "发布机构中文用法及研究概述", "category": "fundamentals"}, {"id": "public-assembly-building", "en": "Public assembly building", "zh_display": "公众活动类建筑〔GB55031功能类别对应，非逐字英译〕", "definition_zh": "供人群开展休闲、运动、参观、观演、集会、社交及宗教信徒聚会等活动的建筑，原词条举剧院、博物馆、会展中心和礼拜场所为例。具体统计或消防制度的使用类别仍须按各自规则判定。", "scope_note": "", "name_basis": "GB55031—2022第2.1.4条文说明的公众活动类建筑涵盖休闲、运动、参观、观演、集会、社交及宗教信徒聚会，与原网页events、culture、worship的总体功能相符，可以采用已有国标中文类别作有据对应。原网页剧院、博物馆、会展中心和礼拜场所是举例而非排除其他公众活动的边界，不能仅凭例子较少便判定中文类别不适用。EIA将宗教独立分类是另一制度的规则，亦不能反向规定SBDB范围；具体制度不应混用。", "evidence_note": "GB55031—2022正文列公众活动功能，条文说明直接使用并解释“公众活动类建筑”；与原站作功能类别对应，不冒称标准提供Public assembly building的正式英中对照。", "category": "building-types"}, {"id": "public-sector-building", "en": "Public sector building", "zh_display": "政府和公营机构建筑物〔香港政府组合用语〕", "definition_zh": "以政府或公共部门拥有、管理或使用为划分依据的建筑类别，可包括政府办公、法院、警消及其他公共部门设施。它按所属或使用主体分类，与按功能划分的“公共建筑”不同；具体机构及产权边界依所采用制度确定。", "scope_note": "", "name_basis": "香港政府2026-07-08答复第(3)项直接以“公营机构建筑物”对应public sector buildings，并将政府建筑物另列；后文实际原文组合为“政府和公营机构建筑物”，对应government and public sector buildings。可按原站政府/公共部门建筑的整体范围采用此限定名称，不声称单独英文Public sector building与组合标题逐字相同，不再全面保留英文。", "evidence_note": "香港政府自行发布的中英文议会书面答复，中文组合用语有直接对应；不是单独英文标题的逐字官方译名，也不是全国统一类别定义。", "category": "building-types"}, {"id": "realestatecore", "en": "RealEstateCore", "zh_display": "RealEstateCore", "definition_zh": "用于描述房地产中的建筑、空间、资产、设备及关系的开放本体，支持数字孪生和运营数据建模；具体实现和版本须分别确定。", "scope_note": "", "name_basis": "Microsoft与RealEstateCore合作的官方中文文档采用“RealEstateCore本体”，保留项目专名RealEstateCore。", "evidence_note": "官方中文内容有据概述（范围及版本见文）", "category": "protocols-standards"}, {"id": "relative-humidity", "en": "Relative humidity", "zh_display": "相对湿度", "definition_zh": "空气实际水汽压与同一温度下所采用基准的饱和水汽压之比，通常用百分数表示。一般室内环境使用水面饱和基准；涉及冰面基准时应明确说明，不能将相对湿度等同水蒸气绝对含量。", "scope_note": "", "name_basis": "同温度饱和水汽压比值方向正确；进一步注明通常以水面为基准，涉及冰面时须标明。WMO明确水/冰基准应随元数据说明，原句在低温语境有歧义。", "evidence_note": "政府中文名称及比值定义；WMO一手说明补充水面/冰面基准，非逐字同一条文", "category": "health-occupancy"}, {"id": "renewable-energy", "en": "Renewable energy", "zh_display": "可再生能源", "definition_zh": "可从自然界持续获得的非化石能源，包括太阳能、风能、水能、生物质能、地热能和海洋能等。", "scope_note": "", "name_basis": "依2025年起施行的《能源法》中文法定术语概述。", "evidence_note": "能源法中文法定定义概述", "category": "energy-sustainability"}, {"id": "reset", "en": "RESET", "zh_display": "RESET标准", "definition_zh": "以数据质量和透明度为核心的模块化建筑环境标准与评估工具，涵盖运营及隐含性能等领域；RESET Air是其中的空气模块。", "scope_note": "", "name_basis": "官方中文保留RESET。原站若只介绍RESET Air，应注明它是RESET体系中的空气模块，不能覆盖全体系。", "evidence_note": "制定组织中文标准介绍概述", "category": "certifications-ratings"}, {"id": "restaurant", "en": "Restaurant", "zh_display": "餐馆", "definition_zh": "接待顾客就餐或宴请的营业性场所，可独立成栋或设置在其他建筑内。", "scope_note": "", "name_basis": "中文标准条文概述", "evidence_note": "中文标准条文概述", "category": "building-types"}, {"id": "retail-building", "en": "Retail building", "zh_display": "商店建筑〔对应本词零售用途〕", "definition_zh": "以向最终消费者直接销售商品及提供相关服务为主要用途的建筑；中文“商业建筑”的范围通常更广。", "scope_note": "", "name_basis": "商店建筑是正式中文标准类别，功能与原网页零售用途对应，可用于文档导航命名；必须说明是类别对应，不能声称JGJ 48英文条目写Retail building。新见政府“零售大厦”仅为特定地址，不作为通用术语定名依据。", "evidence_note": "中国正式标准相关类别；不是宣称标准英文条目逐字为Retail building", "category": "building-types"}, {"id": "retrofit", "en": "Retrofit", "zh_display": "改造〔施耐德楼宇技术资料用语〕", "definition_zh": "对既有建筑或其系统增设技术、更新部件或调整配置，以提升性能、功能或适应新要求的活动；节能改造是其中一类，不能将全部改造限定为节能工程。", "scope_note": "", "name_basis": "施耐德中文出版物以“改造建筑”为题，文档编号明确为Retrofit-Buildings-Net-Zero；其楼宇BMS技术帮助同一页将retrofit projects小节表述为“改造项目”，内容是利用既有网络与布线完成控制系统升级，已不限于狭义能耗改善。可采用“改造”并标明企业楼宇技术语境，不再因未取得全国统一词条而全部保留英文；不能据此宣称renovation、refurbishment、rehabilitation与retrofit严格同义。联合国A/75/181第34段另将retrofitting of buildings译为“翻新建筑物”，可作为存在不同机构用词的说明，不据此指定唯一中文名。", "evidence_note": "头部企业正式中文资料中的直接用法；定义为建筑技术语境的有据概述，非统一标准逐字定义", "category": "fundamentals"}, {"id": "school", "en": "School", "zh_display": "学校", "definition_zh": "供教育和教学活动使用的机构或场所；本网页建筑分类主要指学前、小学至中学阶段的教学及相关服务场所。具体机构和学段边界依适用教育或规划制度确定。", "scope_note": "", "name_basis": "香港城市规划委员会词汇释义直接列学校（School）并有实质定义，前版仅以教育建筑为相关上位概念而保留School过于保守。普通名称可用，香港具体人数门槛不推广到通用定义。", "evidence_note": "政府直接中英对照名称及实质释义；通用概述不照搬地方人数门槛", "category": "building-types"}, {"id": "scope-1-2-and-3-emissions", "en": "Scope 1, 2 and 3 emissions", "zh_display": "范围一、范围二和范围三排放", "definition_zh": "组织温室气体核算中的分类：范围一为拥有或控制排放源的直接排放；范围二为外购并消耗的电力、蒸汽、热力或冷量所产生的间接排放；范围三为价值链其他间接排放。", "scope_note": "", "name_basis": "采用GHG Protocol官方中文用语；这里的范围是组织核算分类，与建筑生命周期阶段并非一一对应。", "evidence_note": "制定组织中文定义及范围二英文指导补充", "category": "energy-sustainability"}, {"id": "semantic-data-model", "en": "Semantic data model", "zh_display": "语义数据模型", "definition_zh": "明确描述实体、属性、含义及关系的数据模型，使软件能理解数据所代表的对象；建筑应用可表达空间、设备与测控点之间的联系。", "scope_note": "", "name_basis": "中文“语义数据模型”可在微软官方Analysis Services文档核查；Fabric资料补充模型含义，建筑范围以ASHRAE说明补充。上述软件中的具体模型并不与所有建筑语义本体完全等同。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "data-software"}, {"id": "service-building", "en": "Service building", "zh_display": "居民服务建筑〔国标用途类别对应〕", "definition_zh": "以向公众提供日常生活服务为主要用途的建筑，例如邮政、维修、洗染、洗车和车辆服务站等；具体用途和统计归类应按所采用标准确定。", "scope_note": "“居民服务建筑”按GB/T50841—2013用途类别作对应，非Service building逐字官方对译。该国标类别还含餐饮、金融营业、电信等用房，并对非独立使用的情形另有限定；EIA的Service类别则排除餐饮和商品零售。原网页未明文采用这项EIA排除规则。", "name_basis": "GB/T50841—2013《建设工程分类标准》第3.2.6条直接列出并说明“居民服务建筑”，包括邮政、洗染、理发美容、家电维修等生活服务用途。原网页给出邮局、洗车、维修店和车辆服务站等日常服务实例，没有明文规定排除餐饮或商品零售。因此可按功能用途采用已有中文类别，并保留“国标用途类别对应”限定；不声称原标准列有Service building这一英文术语的逐字中文对译。", "evidence_note": "已发布国家标准正文的中文类别及政府文件同名用法；以功能用途作对应。释义综合原网页、国标类别说明及EIA分类差异，不是任何一份文件的逐字统一定义。", "category": "building-types"}, {"id": "setpoint", "en": "Setpoint", "zh_display": "设定值", "definition_zh": "控制系统要求受控变量达到或跟踪的目标值，可固定，也可随时程、工况或上层控制策略变化；区别于传感器实测值。", "scope_note": "", "name_basis": "NI和西门子官方中文技术资料用“设定值”，NI明确定义为过程变量的期望值。", "evidence_note": "技术开发商官方中文术语说明的概述", "category": "systems-controls"}, {"id": "sick-building-syndrome", "en": "Sick building syndrome", "zh_display": "病态建筑综合征〔SBS〕", "definition_zh": "建筑使用者出现与在建筑内停留时间相关的急性健康不适或舒适度问题，离开后常缓解，但未能识别特定疾病或明确原因的情形；应与能够诊断并确定建筑相关病因的建筑相关疾病区分。", "scope_note": "", "name_basis": "原稿“明确原因可能不清楚”不足以限定SBS。EPA原始定义强调未能识别特定疾病或原因，并与可诊断的建筑相关疾病BRI区分；补充离开后常缓解及这一边界。", "evidence_note": "疾控中文用名；EPA原始概念说明明确SBS与可诊断BRI边界，非个体诊断标准", "category": "health-occupancy"}, {"id": "single-family-home", "en": "Single-family home", "zh_display": "独户住宅〔西雅图政府用语〕", "definition_zh": "供一户家庭居住的个体住宅。部分统计方案既包括独立式房屋，也包括符合地块和使用条件的共墙住宅，不必然全部独立成栋。", "scope_note": "", "name_basis": "西雅图市政府正式中英双语《租客手册》把single-family home对应“独户住宅”；有政府中文用法，不是本次自行翻译。", "evidence_note": "西雅图市政府正式中英双语《租客手册》把single-family home对应“独户住宅”；有政府中文用法，不是本次自行翻译。", "category": "building-types"}, {"id": "small-cell", "en": "Small cell", "zh_display": "小基站〔Small Cell〕", "definition_zh": "为较小区域提供蜂窝接入覆盖或局部容量增强的无线接入设备及部署形式，需要相应回传连接；区别于传统DAS信号分配系统。", "scope_note": "", "name_basis": "华为中文资料采用“小基站”，具体设备功率、覆盖半径及制式随产品变化。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "connectivity"}, {"id": "smart-building", "en": "Smart building", "zh_display": "智慧建筑〔香港绿色建筑议会用语〕", "definition_zh": "运用自动化、综合楼宇管理、数字基础设施、数据采集和远程监控等技术，使建筑系统互联并与使用者互动，通过数据分析改善运行效率、空间利用、舒适度、安全及健康等整体表现的建筑。", "scope_note": "", "name_basis": "补得制定／专业机构正式中文实质说明，前版因smart与intelligent不逐词相同而全面保留英文过于保守。智慧建筑可用；在研国家标准计划只能佐证命名，不能当作已发布国家标准定义。", "evidence_note": "专业机构正式中文实质说明；国家标准在研计划仅补强命名，非已发布国标定义", "category": "fundamentals"}, {"id": "smart-building-platform", "en": "Smart building platform", "zh_display": "智能建筑平台〔政府公开研究用语〕", "definition_zh": "连接多个建筑系统和设备，汇集和组织运行数据，为数据访问、监测、分析及其他应用提供共同基础的平台；控制能力、部署形式和开放程度须按具体实现确定。", "scope_note": "", "name_basis": "交通部运输研究所公开研究文本直接使用“智能建筑平台（Smart Building Platform）”；足以补强中文用法，不应继续以完全未核中文名处理。报告对特定产品的描述不能成为全体平台必备功能。", "evidence_note": "政府公开研究报告中的中英文用法；概念范围另据原始平台技术资料，不称统一标准定义", "category": "data-software"}, {"id": "smart-building-score", "en": "Smart Building Score", "zh_display": "Smart Building Score", "definition_zh": "Smart Building Database依据公开证据建立的0—100分自有指标，评价认证、智能化、性能和数据可信度；不是认证，也不同于SmartScore。", "scope_note": "", "name_basis": "本词条由SBDB自行定义；未检得SBDB发布的中文名或中文释义，保留Smart Building Score。", "evidence_note": "未检得可直接对应的官方中文释义；下述技术核对据外文一手资料，不作为官方中文定义。", "category": "certifications-ratings"}, {"id": "smart-city", "en": "Smart city", "zh_display": "智慧城市", "definition_zh": "利用信息通信技术整合城市系统、共享信息和协同业务，改善城市治理、公共服务、居民福祉及资源利用，支持可持续发展的城市。", "scope_note": "", "name_basis": "正式标准题名＋政府公开草案释义概述", "evidence_note": "正式标准题名＋政府公开草案释义概述", "category": "fundamentals"}, {"id": "smart-readiness-indicator", "en": "Smart Readiness Indicator", "zh_display": "SRI；智慧就绪指标〔政府研究用语〕", "definition_zh": "评价建筑利用智能服务维持能效与运行、响应使用者需求，以及调节能源需求以响应能源网络的能力的欧盟评价方案。", "scope_note": "", "name_basis": "台湾内政部建筑研究所2024年前后研究报告中英并列“智慧就緒指標（Smart readiness indicator）”；是政府研究用语，未据欧盟制定方确认唯一中文名。", "evidence_note": "有政府中文研究介绍，未取得欧盟正式中文制度文本。", "category": "certifications-ratings"}, {"id": "smartscore", "en": "SmartScore", "zh_display": "SmartScore认证", "definition_zh": "WiredScore发布的智慧建筑认证，评价使用者功能及技术基础等智能能力，区别于其数字连接认证及SBDB的自有评分。", "scope_note": "", "name_basis": "官方中文直接称“SmartScore认证”，未自行创造中文品牌名。", "evidence_note": "制定组织中文认证说明概述", "category": "certifications-ratings"}, {"id": "soft-landings", "en": "Soft Landings", "zh_display": "Soft Landings", "definition_zh": "贯穿任务书、设计、施工、移交和使用初期的建筑交付框架，提前规划运行成果，并通过后续支持、调校和使用后评价检验目标。", "scope_note": "", "name_basis": "保留Soft Landings。内政部建研所2020年CDE研究第14页使用“政府軟著陸”对应Government Soft Landings；这是英国政府实施方案的中文研究用语，不能直接视为BSRIA整个Soft Landings框架的制定方中文名。", "evidence_note": "保留Soft Landings。内政部建研所2020年CDE研究第14页使用“政府軟著陸”对应Government Soft Landings；这是英国政府实施方案的中文研究用语，不能直接视为BSRIA整个Soft Landings框架的制定方中文名。", "category": "fundamentals"}, {"id": "solar-pv", "en": "Solar PV", "zh_display": "光伏发电〔PV〕", "definition_zh": "利用太阳电池的光生伏打效应，将太阳辐射能直接转换为电能的技术，区别于太阳能热利用。", "scope_note": "", "name_basis": "名称只采用可核来源实际用词；介绍仅取官方技术定义，不沿用该2014页面中的旧项目管理政策。", "evidence_note": "政府中文技术定义概述", "category": "energy-sustainability"}, {"id": "split-incentive", "en": "Split incentive", "zh_display": "分裂激励〔联合国中文报告用语〕", "definition_zh": "承担节能投资支出或作出投资决策的主体，与获得节能收益的主体不一致，因而削弱投资或节能动力的情形；出租建筑中业主和租户之间的关系是典型例子。", "scope_note": "", "name_basis": "已直接下载并核读A/75/181中英文原PDF，第35段中文写“分裂激励”，英文同段写split incentives。正文恰为房主无法从住宅能效改善中获得收益而投资不足的建筑节能问题，名称与语境吻合，可撤销未取得任何可靠中文用法的结论。该报告是极端贫困与人权问题特别报告员报告，由秘书长转递大会；不是专门术语标准，不能称全国唯一正式译名。", "evidence_note": "联合国中英正式文件直接对应名称及建筑节能实例；概括定义另与政府一手说明互证", "category": "fundamentals"}, {"id": "stadium-and-arena", "en": "Stadium and arena", "zh_display": "体育场及体育馆〔场馆类别对应〕", "definition_zh": "供体育比赛、演出及其他大型活动使用并容纳观众的场馆，包括体育场、体育馆等。arena可指整个场馆，也可能在设计或运营文件中特指竞赛区或表演场，应结合语境理解。", "scope_note": "", "name_basis": "原定义将室外体育场与室内场馆作硬分不够稳妥，场馆可有覆盖或可开合屋盖。改按体育/演出及观众活动功能定义，保留arena整体场馆与竞赛区层级差异。", "evidence_note": "政府双语项目与中文场馆标准提供类别名称，定义按场馆功能概述，屋盖形态不作为硬分类条件", "category": "building-types"}, {"id": "stranded-asset", "en": "Stranded asset", "zh_display": "搁浅资产", "definition_zh": "因技术、市场、商业环境或公共规则等变化，预期收益意外改变而发生贬值或成为负担的资产；风险预警不等于损失已发生。", "scope_note": "", "name_basis": "IPCC官方中文名称为“搁浅资产”；CRREM偏离路径指标与确定的金融损失需严格区分。", "evidence_note": "IPCC中文名称证据＋英文IPCC术语表概述", "category": "energy-sustainability"}, {"id": "structured-cabling", "en": "Structured cabling", "zh_display": "综合布线；结构化布线", "definition_zh": "按标准组织的通信布线基础设施，以水平、主干等子系统和连接接口支持语音、数据、视频及建筑系统，提供可管理、可扩展的连接基础。", "scope_note": "", "name_basis": "康普官方中文页同时采用“结构化布线”“结构化综合布线”“综合布线”，此处均保留；不直接将structured cabling等同于以太网布线。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "connectivity"}, {"id": "submetering", "en": "Submetering", "zh_display": "分表计量；分项计量〔建筑用能按用途细分语境〕", "definition_zh": "在总计量之下，对不同区域、租户、系统或设备等分别计量的做法，可涉及电、冷热量、水或燃气；按用途分项和按租户分户属于不同划分口径，应分别说明。", "scope_note": "", "name_basis": "国家统计局官网托管EIA讲者双语培训资料使用分表计量；建研所建筑用电中英研究使用分项计量。不得将政府托管资料进一步无证称EIA审定的唯一官方中文译名。", "evidence_note": "政府官网托管双语培训材料直接支持submetering/分表计量；政府建筑研究机构中英摘要支持用电sub-metering/分项计量。两者均不是涵盖全部场景的统一术语标准，定义为注明边界的综合概述。", "category": "systems-controls"}, {"id": "tall-building", "en": "Tall building", "zh_display": "高层建筑〔CTBUH历史中文用语〕", "definition_zh": "高度显著影响环境、比例或工程技术要求的建筑。原CTBUH（现Council on Vertical Urbanism，CVU）的高度准则不设全球统一绝对起点；其中supertall为300米及以上，megatall为600米及以上。", "scope_note": "", "name_basis": "300/600米高度类别无新错误，但CTBUH已于2025-10-06更名Council on Vertical Urbanism（CVU）。旧中文期刊可作历史命名依据，当前说明须标原名/现名，不把旧机构名无条件当现状。", "evidence_note": "旧CTBUH中文文献为历史命名依据；现CVU官方更名说明及其Skyscraper Center高度准则，非中国法定高层划分", "category": "building-types"}, {"id": "telecoms-riser", "en": "Telecoms riser", "zh_display": "垂直干管〔NCC电信法规用语〕", "definition_zh": "供建筑电信线缆逐层敷设的竖向管路。工程资料中的telecoms riser亦可泛指相应竖向布线路径或预留空间；应结合语境区分管路、管道间和竖向空间，建筑入口管道另行识别。", "scope_note": "", "name_basis": "NCC中英对照法规明确以“垂直干管”对应riser。原站混入建筑入口是其定义需修正的地方，不足以否定正确术语；但不能把NCC对管路的名称无条件扩大为整个建筑竖井或入口。", "evidence_note": "政府现行中英对照法规中的riser名称；广义路径及空间范围另据通信监管机构英文说明", "category": "connectivity"}, {"id": "tenant-experience-app", "en": "Tenant experience app", "zh_display": "租户应用程序〔恒基地产项目中文用语，功能类别对应〕", "definition_zh": "面向建筑租户及其他使用者的移动数字服务入口，可按物业配置集成楼宇信息、服务申请、设施预订、访客或门禁、环境调节及活动等功能；具体功能与使用权限依项目确定。", "scope_note": "企业原文使用“专属租户应用程序”“租户应用程式”等名称。此处按楼宇体验服务功能对应，不自行添加“体验”并宣称为来源中的正式题名，也未确认统一标准译名。", "name_basis": "恒基兆业地产The Henderson官方简体中文页在“租户体验”部分直接列“专属租户应用程序”，英文同位置为“BESPOKE TENANT APP”，说明可调节个人环境、处理日常事务并联系楼宇社群。泓富产业信托2022中文报告另直接使用“租户应用程式”，描述一站式楼宇通知、服务及设施预订、延长空调、活动和优惠；官方中英使用条款分别称“租户流动应用程式”与“Tenant mobile application”。这已是针对本类楼宇体验服务的应用名称，证据强于前轮只有“手机应用程序”这一上位词。采用来源限定的功能对应名称，不自行添入“体验”拼成来源未用的正式题名。", "evidence_note": "头部地产企业官方项目中英文页面中的直接名称及同功能说明；上市房地产信托自发中文报告和中英应用条款互证。可作企业中文名称或功能类别对应，未确认全国统一术语或Tenant experience app完整标题的逐字官方对译。中文释义为依据一手资料整理的概述。", "category": "data-software"}, {"id": "thermal-comfort", "en": "Thermal comfort", "zh_display": "热舒适", "definition_zh": "人对热环境表示满意的主观状态，受空气温度、平均辐射温度、风速、湿度、着装及活动共同影响；PMV和PPD是评价指标而非同义词。", "scope_note": "", "name_basis": "GB/T33658—2025正式名称使用“热舒适”；目录页只证名称及现行状态，未从该页取得完整中文定义。", "evidence_note": "中文国标名称已核；ASHRAE英文一手定义的中文概述", "category": "health-occupancy"}, {"id": "thermal-energy-storage", "en": "Thermal energy storage", "zh_display": "储热（TES）；另见“热储能”用法", "definition_zh": "将热或冷储存并在其他时间取用，以调节供热或供冷的供需；具体形式包括水、冰、相变或建筑主体等储能。", "scope_note": "", "name_basis": "新增IRENA正式中文出版物题名储热与国合会术语表热储能，证据优于仅依供应商；不宣称全国唯一标准名。", "evidence_note": "IRENA官方中文出版物用储热；国合会报告术语表用热储能；无证据据此指定全国唯一标准词", "category": "energy-sustainability"}, {"id": "thread", "en": "Thread", "zh_display": "Thread", "definition_zh": "基于IPv6的低功耗无线Mesh组网协议，可通过边界路由器连接其他IP网络；属于连接技术，不等同于Matter应用层标准。", "scope_note": "", "name_basis": "保留制定方原名／标准编号；中文说明是应用或范围描述，不自行拼接成正式中文专名。联盟中文资料保留Thread，不翻译为计算机程序中的“线程”。", "evidence_note": "制定／标准组织自身中文资料概述", "category": "protocols-standards"}, {"id": "time-series-database", "en": "Time series database", "zh_display": "时间序列数据库；时序数据库", "definition_zh": "面向带时间戳数据的存储和查询系统，通常优化持续写入、时间范围检索、聚合及生命周期管理，可记录状态、事件和传感观测。", "scope_note": "", "name_basis": "官方中文采用“时间序列数据库”，常简称“时序数据库”。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "data-software"}, {"id": "transport-building", "en": "Transport building", "zh_display": "交通建筑", "definition_zh": "为交通运输服务的公共建筑，依交通方式与功能可包括航站楼、铁路或公路客运站、轨道交通站及港口客运设施等。", "scope_note": "", "name_basis": "中文标准条文概述", "evidence_note": "中文标准条文概述", "category": "building-types"}, {"id": "trend-log", "en": "Trend log", "zh_display": "趋势日志〔厂商中文用语〕", "definition_zh": "按时间记录测控值及相关信息的历史日志，用于观察变化、诊断和分析；BACnet的Trend Log另是具有规定属性和记录规则的对象类型。", "scope_note": "", "name_basis": "中文“趋势日志”已有原发布者手册直接证据，适合作中文主名；BACnet标准对象仍保留Trend Log原名以区别特定协议对象与一般记录。", "evidence_note": "厂商正式中文手册用语及说明；BACnet对象补充据英文一手文档", "category": "data-software"}, {"id": "trias-energetica", "en": "Trias Energetica", "zh_display": "Trias Energetica", "definition_zh": "按优先次序作能源决策的三步原则：先减少需求，再采用可再生能源，最后尽可能高效利用仍需使用的化石或其他不可再生能源。", "scope_note": "", "name_basis": "中德合作项目中文指南沿用Trias Energetica；未据荷兰RVO确认正式中文专名，保留英文。", "evidence_note": "中德合作项目中文指南沿用Trias Energetica；未据荷兰RVO确认正式中文专名，保留英文。", "category": "fundamentals"}, {"id": "urban-mining", "en": "Urban mining", "zh_display": "Urban mining；城市采矿〔IURC China项目中文用语〕", "definition_zh": "将既有建筑、基础设施、设备及废弃产品视为资源存量，回收可再使用构件和材料的活动；资源存量名称不等于活动的正式中文名。", "scope_note": "", "name_basis": "新增IURC China官方项目中文材料的城市采矿用法，可列来源限定名；它不是国家术语标准，不能改称唯一法定名。", "evidence_note": "欧盟国际城市合作项目发布中文用法；非国家标准术语或中国政策唯一正式名", "category": "energy-sustainability"}, {"id": "variable-air-volume", "en": "Variable air volume", "zh_display": "变风量空调系统〔VAV〕", "definition_zh": "在送风温度基本稳定时，通过改变机组或末端送风量控制室内空气温度的全空气空调系统；VAV box是末端装置，非整个系统。", "scope_note": "", "name_basis": "JGJ 343—2014第2.0.1条中英直接对应“变风量空调系统／variable air volume air conditioning system”。", "evidence_note": "中文工程建设标准定义的概述（研究机构公开文本）", "category": "systems-controls"}, {"id": "variable-refrigerant-flow", "en": "Variable refrigerant flow", "zh_display": "变制冷剂流量系统〔VRF〕", "definition_zh": "由共享室外机和多台室内机等构成，按负荷调节制冷剂供给以满足不同区域空调需求的系统；VRV属于厂商品牌用语。", "scope_note": "", "name_basis": "开利官方中文产品名“变制冷剂流量（VRF）系统”；UNEP U4E中文资料也用“变制冷剂流量”。GB/T18837—2026对应设备类别“多联式空调（热泵）机组”，不是完全同一个英文题名。", "evidence_note": "厂商与国际组织中文名称/技术说明的概述", "category": "systems-controls"}, {"id": "variable-speed-drive", "en": "Variable speed drive", "zh_display": "变速驱动器〔VSD〕", "definition_zh": "按运行需求调节电动机转速的驱动装置。交流变频驱动是常见实现方式，但VSD的范围比变频器或VFD更宽。", "scope_note": "", "name_basis": "UNEP U4E官方中文缩略词表明确VSD为“变速驱动器”；丹佛斯“可调速驱动器”在交流驱动讨论中使用，不宣称所有VSD等于VFD。", "evidence_note": "国际组织中文名称及厂商/政府技术说明概述", "category": "systems-controls"}, {"id": "vehicle-to-grid", "en": "Vehicle-to-grid", "zh_display": "车网双向互动／双向充放电〔V2G〕", "definition_zh": "电动汽车通过支持双向能量流的设施从电网充电，并可将电能回送电网；车向建筑供电V2B及单向有序充电应分别识别。", "scope_note": "", "name_basis": "官方“车网互动”还包括单向有序充电，范围比通常狭义V2G更广；本条明确选用双向语境。", "evidence_note": "官方中文用法或相关概念＋一手技术资料综合概述，非统一中文定义条文", "category": "energy-sustainability"}, {"id": "vendor-lock-in", "en": "Vendor lock-in", "zh_display": "供应商锁定", "definition_zh": "由于技术、数据格式、许可、合同或转换成本等障碍，客户难以更换现有供应商的状态；采用单一供应商本身不必然构成锁定。", "scope_note": "", "name_basis": "厂商正式中文解释概述", "evidence_note": "厂商正式中文解释概述", "category": "fundamentals"}, {"id": "ventilation-rate", "en": "Ventilation rate", "zh_display": "通风量〔GB/T50155暖通语境〕", "definition_zh": "在暖通术语中，指单位时间内进入室内或从室内排出的空气量，常以L/s或m³/h表示。讨论室外空气供应时应明确为新风量；换气次数则以相应流量除以空间体积，通常用h⁻¹表示。部分领域文献也把ventilation rate用于换气次数，应结合单位和定义判断，并注明新风或总风口径。", "scope_note": "", "name_basis": "GB/T50155—2015第4.1.14条直接列出通风量ventilation rate，第4.1.15条另列换气次数air change rate。原先因网页偏重新风而完全保留英文过度保守；同时英文ventilation rate跨领域存在指换气次数的用法，不能断言其永远不指ACH。《环境卫生学名词》2025征求意见稿仅作跨领域用法提示，不当作已正式审定术语。", "evidence_note": "GB/T50155—2015正式中英术语及定义；另有不同领域的英文用法，不能用单一中文排除其他口径", "category": "health-occupancy"}, {"id": "video-analytics", "en": "Video analytics", "zh_display": "视频分析〔厂商用语〕", "definition_zh": "使用算法从视频或图像中识别人员、车辆、物体、行为或事件，形成可供安防和运营使用的信息；区别于单纯视频监控。", "scope_note": "", "name_basis": "火山引擎官方文档使用“视频分析”“智能视频分析”，后者为具体平台/产品名称；不把特定产品定义当作通用国标定义。", "evidence_note": "厂商自身中文产品技术说明的概述", "category": "systems-controls"}, {"id": "visitor-management", "en": "Visitor management", "zh_display": "访客管理", "definition_zh": "围绕外来访客开展预约、审批、登记、通行权限分配及到访记录管理的流程及相关系统功能。", "scope_note": "", "name_basis": "海康威视官方中文方案名称直接用“访客管理”；为系统产品功能用法，非统一行业标准定义。", "evidence_note": "厂商自身中文方案功能的概述", "category": "systems-controls"}, {"id": "vocs", "en": "VOCs", "zh_display": "挥发性有机物〔VOCs〕", "definition_zh": "具有挥发性的一类有机化合物，具体纳入范围和测定条件随标准而定；室内TVOC是按指定方法得到的总量指标，不能与VOCs类名等同。", "scope_note": "", "name_basis": "GB37822—2019第3.1条名称为“挥发性有机物”；GB/T18883—2022第3.4条另定义“总挥发性有机化合物（TVOC）”，具体口径不同。", "evidence_note": "中文国家环境标准术语及室内空气标准相关术语的对照概述", "category": "health-occupancy"}, {"id": "warehouse-and-distribution-centre", "en": "Warehouse and distribution centre", "zh_display": "仓库及配送中心〔并列设施类别〕", "definition_zh": "仓库侧重货物储存保管，配送中心还承担集货、分拣、组配及配送组织等功能；可共处同一场址，但不是完全同义的设施。", "scope_note": "", "name_basis": "仓库与配送中心分别已有官方中文依据，可将两个既有设施名称并列展示；前版要求整个并列标题存在一条独立术语才可中文命名过严。需注明这是并列类别，不能声称二者同义或为单一官方定义。", "evidence_note": "两个分别有政府／标准用法的中文设施名称并列，非声称存在同名单一定义", "category": "building-types"}, {"id": "water-recycling", "en": "Water recycling", "zh_display": "水回用；亦称水循环利用〔AWS、工研院中文用语〕", "definition_zh": "有目的地收集不同来源的水，按预定用途进行必要处理，加以利用或再次利用。在本建筑词条语境中，来源可包括灰水、雨水和空调冷凝水等，用于冲厕、灌溉等符合水质要求的用途；各类水源的处理与管理要求应分别确定。", "scope_note": "", "name_basis": "工研院技术服务网页直接列“水循环利用(Water Recycling)”，服务范围涵盖工业及民生，已不限既有国标产业园区题名。该页把雨水贮留作为广义节水替代水源另列，不能声称这一行独自定义所有建筑非传统水源。另已直接核读AWS中国办公室3.0中文文件（文件名含Final-Draft，首页却明确标为2025-12-15成员已批准定稿），第21页写水回用Water reuse并称也叫水循环利用；当前2026年3月正式英文版同条明确water reuse又称water recycling，覆盖废水、雨水等。正式排版的中文3月文件搜索索引亦可见同词，但原直链本轮404，因此未伪称已直接读到该版全文。定义采用中文概述，并由EPA广义水回用及工研院冷凝水/雨水实际服务条目补足建筑范围。", "evidence_note": "AWS中国办公室发布的成员已批准中文定稿明确名称与释义；2026年3月英文正式版核对同一术语；工研院直接中英用法互证；建筑水源范围另据EPA和工研院技术服务说明", "category": "energy-sustainability"}, {"id": "wayfinding", "en": "Wayfinding", "zh_display": "Wayfinding；寻路〔HPE用语〕", "definition_zh": "帮助人员确定位置、选择路线并到达目的地的信息与服务，可通过空间导向、标识、地图或数字导航实现，不必依赖实时手机定位。", "scope_note": "", "name_basis": "补香港运输署中英文材料，支持标示、地图与导向系统可实现wayfinding；未将更窄的行人标示系统当作广义寻路行为的唯一定义。", "evidence_note": "厂商中文直接用语；政府中文“行人导向系统”为相关实现概念，不强称同一层次的术语", "category": "data-software"}, {"id": "well", "en": "WELL", "zh_display": "WELL建筑标准", "definition_zh": "以健康和福祉为核心，评价建筑环境、设计与运营策略的标准及相关认证体系，按所选计划实施文件审核和相应性能验证。", "scope_note": "", "name_basis": "官方资料使用“WELL建筑标准”；“WELL认证”“WELL评价”等计划名称应分别使用，不能混为同一种证书。", "evidence_note": "制定及认证组织中文说明概述", "category": "certifications-ratings"}, {"id": "whole-life-carbon", "en": "Whole life carbon", "zh_display": "全生命周期碳排放", "definition_zh": "建筑从材料生产、运输、建造到使用、维修更换和拆除处理的温室气体排放及按方法计入的清除量，涵盖运行与隐含部分，边界外模块另列。", "scope_note": "", "name_basis": "RICS2024正式中文版直接采用“全生命周期碳排放”；比仅据国内“全生命期”类近义用法有更直接同词证据。", "evidence_note": "专业标准组织中文用法＋英文标准概述", "category": "energy-sustainability"}, {"id": "wi-fi-6", "en": "Wi-Fi 6", "zh_display": "Wi-Fi 6〔IEEE 802.11ax〕", "definition_zh": "基于IEEE 802.11ax的Wi-Fi技术代际，采用OFDMA等机制改善多设备通信效率；Wi-Fi 6E扩展至6 GHz，Wi-Fi 7属于另一代技术。", "scope_note": "", "name_basis": "保留Wi-Fi代际名称，不将其译为“无线保真六代”；不沿用旧资料中“最新一代”的时效性表述。", "evidence_note": "机构或制造商正式中文资料概述，非统一国家标准定义", "category": "connectivity"}, {"id": "wiredscore", "en": "WiredScore", "zh_display": "WiredScore认证", "definition_zh": "评价建筑数字连接基础设施的第三方认证，重点涉及网络接入、运营商选择、移动覆盖及韧性，具体适用项目依方案确定。", "scope_note": "", "name_basis": "官方中文保留WiredScore品牌；与主要评估智能技术及体验的SmartScore区分。", "evidence_note": "制定组织中文认证说明概述", "category": "certifications-ratings"}, {"id": "zero-trust", "en": "Zero trust", "zh_display": "零信任", "definition_zh": "取消仅凭网络位置或既有连接赋予的默认信任，按身份、设备和风险等验证访问，并实施最小权限和持续评估的安全策略与架构方法。", "scope_note": "", "name_basis": "现行GB/T43696-2024正式题名采用“零信任”；定义内容本轮根据Microsoft中文概述，目录本身未被当作全文定义。", "evidence_note": "现行国标名称证据；具体说明依据Microsoft官方中文", "category": "data-software"}, {"id": "zigbee", "en": "Zigbee", "zh_display": "Zigbee", "definition_zh": "连接标准联盟维护的面向物联网的全栈无线网状网络技术，用于住宅、商业、能源及工业监测控制，互通取决于协议和应用实现。", "scope_note": "", "name_basis": "保留制定方原名／标准编号；中文说明是应用或范围描述，不自行拼接成正式中文专名。联盟中文介绍直接使用Zigbee；未采用未经该来源确认的“紫蜂”等译名。", "evidence_note": "制定／标准组织自身中文资料概述", "category": "protocols-standards"}];
export const GlossaryCategories = [{"id": "fundamentals", "name": "基础概念", "count": 18}, {"id": "systems-controls", "name": "系统与控制", "count": 31}, {"id": "protocols-standards", "name": "协议与标准", "count": 22}, {"id": "connectivity", "name": "连接与通信", "count": 11}, {"id": "data-software", "name": "数据与软件", "count": 26}, {"id": "energy-sustainability", "name": "能源与可持续发展", "count": 47}, {"id": "health-occupancy", "name": "健康与空间使用", "count": 13}, {"id": "certifications-ratings", "name": "认证与评级", "count": 24}, {"id": "building-types", "name": "建筑类型", "count": 26}];

export const GlossaryIndex = () => {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("");
  const normalize = value => value.normalize("NFKC").toLocaleLowerCase().replace(/\s+/g, " ").trim();
  const words = normalize(query).split(" ").filter(Boolean);
  const results = GlossaryEntries.filter(entry => (!category || entry.category === category) && words.every(word => normalize([entry.en, entry.zh_display, entry.definition_zh, entry.scope_note, entry.name_basis, entry.evidence_note].join(" ")).includes(word)));
  const letters = [...new Set(results.map(entry => entry.en[0].toUpperCase()))];

  return <div className="pacom-glossary-intro not-prose">
    <style>{`
      .pacom-glossary-intro{--gl-border:#e5e7eb;--gl-muted:#626875;--gl-ink:#202a44;--gl-surface:#f8fafc;color:var(--gl-ink);font-size:14px;line-height:1.65;margin:24px 0 32px}
      .pacom-glossary-intro *{box-sizing:border-box}
      .pacom-glossary-topics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:24px}
      .pacom-glossary-topics button{display:flex;align-items:center;justify-content:space-between;gap:12px;min-width:0;min-height:50px;padding:12px 14px;border:1px solid var(--gl-border);border-radius:6px;background:transparent;color:inherit;text-align:left;font:inherit;cursor:pointer}
      .pacom-glossary-topics button:hover{background:var(--gl-surface)}
      .pacom-glossary-topics button[aria-pressed=true]{border-color:#007eaf;background:rgba(0,174,239,.06)}
      .pacom-glossary-topics small{flex-shrink:0;font-size:11px;letter-spacing:.04em;color:var(--gl-muted);white-space:nowrap}
      .pacom-glossary-toolbar{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:20px}
      .pacom-glossary-search{width:min(100%,360px)}
      .pacom-glossary-search label{display:block;margin-bottom:6px;font-size:12px;color:var(--gl-muted)}
      .pacom-glossary-search input{width:100%;min-height:42px;padding:8px 12px;border:1px solid var(--gl-border);border-radius:6px;background:transparent;color:inherit;font:inherit}
      .pacom-glossary-search input::placeholder{color:var(--gl-muted)}
      .pacom-glossary-status{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:8px;color:var(--gl-muted);font-size:12px}
      .pacom-glossary-status p{margin:0}
      .pacom-glossary-status button{border:0;padding:0;background:transparent;color:#007eaf;font:inherit;cursor:pointer}
      .pacom-glossary-letters{display:flex;flex-wrap:wrap;gap:4px;padding:12px 0 20px;border-bottom:1px solid var(--gl-border)}
      .pacom-glossary-letters a{display:flex;align-items:center;justify-content:center;min-width:32px;min-height:36px;padding:4px 8px;border-radius:4px;color:var(--gl-muted);font-size:13px;font-weight:600;text-decoration:none}
      .pacom-glossary-letters a:hover{color:var(--gl-ink);background:var(--gl-surface)}
      .pacom-glossary-letter{scroll-margin-top:110px;margin-top:36px}
      .pacom-glossary-letter h2{margin:0;padding:0 0 12px;border-bottom:1px solid var(--gl-border);color:inherit;font-size:22px;font-weight:600;line-height:1.4}
      .pacom-glossary-rows{list-style:none;margin:0;padding:0}
      .pacom-glossary-rows li{margin:0;padding:0;border-bottom:1px solid var(--gl-border)}
      .pacom-glossary-row{display:grid;grid-template-columns:minmax(180px,.85fr) minmax(0,1.4fr);gap:28px;padding:18px 0;color:inherit;text-decoration:none;overflow-wrap:anywhere}
      .pacom-glossary-row:hover{background:var(--gl-surface)}
      .pacom-glossary-name{display:block;min-width:0}
      .pacom-glossary-en{display:block;font-size:14px;font-weight:600;line-height:1.5}
      .pacom-glossary-zh{display:block;margin-top:5px;color:var(--gl-muted);font-size:13px;line-height:1.65}
      .pacom-glossary-definition{display:block;color:var(--gl-muted);font-size:13px;line-height:1.8}
      .pacom-glossary-empty{padding:28px 0;color:var(--gl-muted)}
      .pacom-glossary-intro a:focus-visible,.pacom-glossary-intro button:focus-visible,.pacom-glossary-intro input:focus-visible{outline:2px solid #00aeef;outline-offset:3px}
      .dark .pacom-glossary-intro{--gl-border:#383b42;--gl-muted:#a8aab2;--gl-ink:#e5e7eb;--gl-surface:#202329}
      .dark .pacom-glossary-status button{color:#00aeef}
      @media(max-width:680px){.pacom-glossary-topics{grid-template-columns:repeat(2,minmax(0,1fr))}.pacom-glossary-toolbar{align-items:stretch;flex-direction:column;gap:12px}.pacom-glossary-search{width:100%}.pacom-glossary-status{margin:0}.pacom-glossary-row{grid-template-columns:minmax(0,1fr);gap:8px;padding:16px 0}.pacom-glossary-letter{margin-top:28px}}
      @media(max-width:380px){.pacom-glossary-topics{grid-template-columns:minmax(0,1fr)}}
    `}</style>

    <nav className="pacom-glossary-topics" aria-label="主题筛选">
      {GlossaryCategories.map(item => <button key={item.id} type="button" aria-label={"按主题筛选：" + item.name} aria-pressed={category === item.id} onClick={() => setCategory(category === item.id ? "" : item.id)}><span>{item.name}</span><small>{item.count} 条</small></button>)}
    </nav>

    <div className="pacom-glossary-toolbar">
      <div className="pacom-glossary-search"><label htmlFor="glossary-search">搜索术语</label><input id="glossary-search" type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="中文、英文或释义关键词" autoComplete="off" /></div>
      <div className="pacom-glossary-status"><p role="status" aria-live="polite">共 {results.length} 条 · 按英文名称排列</p>{(query || category) && <button type="button" onClick={() => {setQuery("");setCategory("");}}>清除筛选</button>}</div>
    </div>

    <nav className="pacom-glossary-letters" aria-label="字母索引">{letters.map(letter => <a key={letter} href={"#letter-" + letter}>{letter}</a>)}</nav>

    {letters.map(letter => <section className="pacom-glossary-letter" id={"letter-" + letter} key={letter} aria-labelledby={"heading-" + letter}>
      <h2 id={"heading-" + letter}>{letter}</h2>
      <ul className="pacom-glossary-rows">{results.filter(entry => entry.en[0].toUpperCase() === letter).map(entry => <li key={entry.id}><a className="pacom-glossary-row" href={"/glossary/terms/" + entry.id}><span className="pacom-glossary-name"><span className="pacom-glossary-en" lang="en">{entry.en}</span><span className="pacom-glossary-zh">{entry.zh_display}</span></span><span className="pacom-glossary-definition">{entry.definition_zh}</span></a></li>)}</ul>
    </section>)}

    {results.length === 0 && <p className="pacom-glossary-empty">没有匹配术语。可尝试其他关键词或清除筛选。</p>}
  </div>;
};
